#!/usr/bin/env bash
# =============================================================================
# LSSHM - Local SSH Manager
# Version: 0.4.0
# Built:   2026-07-28T13:30:30Z
#
# This file is generated by scripts/build.sh from the modules in src/.
# Do not edit it by hand; edit the modules and rebuild.
#
# A simple local OpenSSH server, client, user access and key management tool
# for Linux (Windows support is planned through lsshm.ps1).
# =============================================================================

set -euo pipefail


# ===== src/common.sh ===================================================
# shellcheck shell=bash
# =============================================================================
# common.sh - shared helpers: version, paths, logging, prompts, temp files
# =============================================================================
# This module has no dependencies on other LSSHM modules and must be sourced
# (or concatenated) first.

# The build script replaces the token below with the content of the VERSION
# file. When running directly from src/ the token stays literal and the guard
# below falls back to a development version string.
LSSHM_VERSION="0.4.0"
case "$LSSHM_VERSION" in
    *@@*) LSSHM_VERSION="0.4.0-dev" ;;
esac

LSSHM_NAME="LSSHM"
LSSHM_LONG_NAME="LSSHM - Local SSH Manager"
LSSHM_REPO_RAW="${LSSHM_REPO_RAW:-https://raw.githubusercontent.com/sannier3/lsshm/preview}"

# -----------------------------------------------------------------------------
# XDG base directories
# -----------------------------------------------------------------------------
lsshm_init_paths() {
    LSSHM_HOME="${HOME:-/root}"
    LSSHM_XDG_CONFIG="${XDG_CONFIG_HOME:-$LSSHM_HOME/.config}"
    LSSHM_XDG_DATA="${XDG_DATA_HOME:-$LSSHM_HOME/.local/share}"
    LSSHM_XDG_STATE="${XDG_STATE_HOME:-$LSSHM_HOME/.local/state}"
    LSSHM_XDG_CACHE="${XDG_CACHE_HOME:-$LSSHM_HOME/.cache}"
    LSSHM_BIN_DIR="$LSSHM_HOME/.local/bin"

    LSSHM_CONFIG_DIR="$LSSHM_XDG_CONFIG/lsshm"
    LSSHM_DATA_DIR="$LSSHM_XDG_DATA/lsshm"
    LSSHM_STATE_DIR="$LSSHM_XDG_STATE/lsshm"
    LSSHM_CACHE_DIR="$LSSHM_XDG_CACHE/lsshm"

    LSSHM_CONFIG_FILE="$LSSHM_CONFIG_DIR/config"
    LSSHM_BACKUP_DIR="$LSSHM_STATE_DIR/backups"
    LSSHM_LOG_FILE="$LSSHM_STATE_DIR/lsshm.log"
    LSSHM_INSTALL_TARGET="$LSSHM_DATA_DIR/lsshm.sh"
    LSSHM_BIN_LINK="$LSSHM_BIN_DIR/lsshm"
}

# -----------------------------------------------------------------------------
# Colors (disabled when not writing to a terminal or NO_COLOR is set)
# -----------------------------------------------------------------------------
lsshm_init_colors() {
    if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${LSSHM_NO_COLOR:-0}" != "1" ] \
        && [ "${LSSHM_UI_MODE:-0}" != "1" ]; then
        LSSHM_C_RESET="$(printf '\033[0m')"
        LSSHM_C_BOLD="$(printf '\033[1m')"
        LSSHM_C_DIM="$(printf '\033[2m')"
        LSSHM_C_RED="$(printf '\033[31m')"
        LSSHM_C_GREEN="$(printf '\033[32m')"
        LSSHM_C_YELLOW="$(printf '\033[33m')"
    else
        LSSHM_C_RESET=""; LSSHM_C_BOLD=""; LSSHM_C_DIM=""
        LSSHM_C_RED=""; LSSHM_C_GREEN=""; LSSHM_C_YELLOW=""
    fi
}

# Remove ANSI escape sequences (dialog and programbox do not render them).
lsshm_strip_ansi() {
    sed $'s/\033\\[[0-9;]*[a-zA-Z]//g'
}

lsshm_strip_ansi_file() {
    local f="$1" tmp
    tmp="$(lsshm_mktemp)"
    lsshm_strip_ansi <"$f" >"$tmp" && mv "$tmp" "$f"
}

# -----------------------------------------------------------------------------
# Logging
# -----------------------------------------------------------------------------
lsshm_log() {
    # lsshm_log LEVEL MESSAGE...
    local level="$1"; shift
    local msg="$*"
    if [ -n "${LSSHM_LOG_FILE:-}" ]; then
        local dir; dir="$(dirname "$LSSHM_LOG_FILE")"
        if [ -d "$dir" ] || mkdir -p "$dir" 2>/dev/null; then
            printf '%s [%s] %s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$level" "$msg" \
                >>"$LSSHM_LOG_FILE" 2>/dev/null || true
        fi
    fi
}

# These helpers take a translatable format string (English msgid) followed by
# optional printf arguments, e.g. lsshm_ok 'Key added for %s.' "$user".
# The message is translated via lsshm_t and formatted with the given arguments.
lsshm_info()  { local m; m="$(lsshm_tf "$@")"; printf '%s\n' "$m"; lsshm_log INFO "$m"; }
lsshm_note()  { local m; m="$(lsshm_tf "$@")"; printf '%s%s%s\n' "${LSSHM_C_DIM:-}" "$m" "${LSSHM_C_RESET:-}" >&2; lsshm_log INFO "$m"; }
lsshm_ok()    { local m; m="$(lsshm_tf "$@")"; printf '%s%s%s\n' "${LSSHM_C_GREEN:-}" "$m" "${LSSHM_C_RESET:-}"; lsshm_log OK "$m"; }
lsshm_warn()  { local m; m="$(lsshm_tf "$@")"; printf '%s%s%s\n' "${LSSHM_C_YELLOW:-}" "$m" "${LSSHM_C_RESET:-}" >&2; lsshm_log WARN "$m"; }
lsshm_error() { local m; m="$(lsshm_tf "$@")"; printf '%s%s%s\n' "${LSSHM_C_RED:-}" "$m" "${LSSHM_C_RESET:-}" >&2; lsshm_log ERROR "$m"; }

lsshm_die() {
    lsshm_error "$@"
    exit 1
}

lsshm_header() {
    printf '%s%s%s\n' "${LSSHM_C_BOLD:-}" "$LSSHM_LONG_NAME" "${LSSHM_C_RESET:-}"
    printf '%sv%s%s\n\n' "${LSSHM_C_DIM:-}" "$LSSHM_VERSION" "${LSSHM_C_RESET:-}"
}

# -----------------------------------------------------------------------------
# Prompts
# -----------------------------------------------------------------------------
# True when stdin/stdout is a TTY, or when /dev/tty is available (IDE
# terminals, sudo, Git Bash on Windows often lack -t 0 but still have /dev/tty).
lsshm_have_tty() {
    [ -e /dev/tty ] 2>/dev/null && [ -r /dev/tty ] && [ -w /dev/tty ]
}

lsshm_is_interactive() {
    [ "${LSSHM_ASSUME_YES:-0}" != "1" ] || return 1
    [ -t 0 ] && [ -t 1 ] && return 0
    lsshm_have_tty && return 0
    return 1
}

lsshm_require_interactive() {
    if lsshm_is_interactive; then
        return 0
    fi
    lsshm_error 'An interactive terminal is required for the menu.'
    lsshm_info 'Without a menu: lsshm status | lsshm doctor | lsshm server status | lsshm key list'
    lsshm_info 'To install: curl -fsSL .../lsshm.sh | bash -s -- install'
    exit 1
}

lsshm_tty_restore() {
    stty sane 2>/dev/null || true
}

lsshm_uses_dialog_ui() {
    [ "${LSSHM_UI_MODE:-0}" = "1" ] && lsshm_have dialog
}

# Read one line from stdin or /dev/tty. Sets the named variable on success.
lsshm_read_line() {
    local __var="$1" __prompt="$2" __line=""
    if [ -t 0 ]; then
        IFS= read -r -p "$__prompt" __line || return 1
    elif lsshm_have_tty; then
        IFS= read -r -p "$__prompt" __line </dev/tty || return 1
    else
        return 1
    fi
    printf -v "$__var" '%s' "$__line"
    return 0
}

lsshm_prompt() {
    # lsshm_prompt PROMPT [DEFAULT] -> echoes answer
    local prompt="$1" default="${2:-}" answer="" msg=""
    if ! lsshm_is_interactive; then
        [ -n "$default" ] && { printf '%s' "$default"; return 0; }
        return 1
    fi
    if lsshm_uses_dialog_ui; then
        lsshm_tty_restore
        answer="$(dialog --inputbox "$prompt" 10 70 "$default" 3>&1 1>&2 2>&3)" || answer="$default"
        printf '%s' "${answer:-$default}"
        return 0
    fi
    if [ -n "$default" ]; then
        msg="${prompt} [${default}]: "
    else
        msg="${prompt}: "
    fi
    if lsshm_read_line answer "$msg"; then
        printf '%s' "${answer:-$default}"
    else
        printf '%s' "$default"
    fi
}

lsshm_confirm() {
    # lsshm_confirm PROMPT [default_yes] -> return 0 for yes
    local prompt="$1" default="${2:-no}" answer="" hint="[y/N]"
    if [ "${LSSHM_ASSUME_YES:-0}" = "1" ]; then
        return 0
    fi
    if ! lsshm_is_interactive; then
        [ "$default" = "yes" ]
        return
    fi
    if lsshm_uses_dialog_ui; then
        lsshm_tty_restore
        if dialog --backtitle "$LSSHM_LONG_NAME v$LSSHM_VERSION" \
            --yesno "$prompt" 10 70 3>&1 1>&2 2>&3; then
            return 0
        fi
        return 1
    fi
    [ "$default" = "yes" ] && hint="[Y/n]"
    if ! lsshm_read_line answer "${prompt} ${hint} "; then
        [ "$default" = "yes" ]
        return
    fi
    answer="$(printf '%s' "$answer" | tr '[:upper:]' '[:lower:]')"
    # Accept English, French and Spanish affirmatives/negatives.
    case "$answer" in
        y|yes|o|oui|s|si|sí) return 0 ;;
        n|no|non)            return 1 ;;
        "")                  [ "$default" = "yes" ] ;;
        *)                   return 1 ;;
    esac
}

lsshm_pause() {
    if lsshm_uses_dialog_ui; then
        return 0
    fi
    lsshm_is_interactive || return 0
    lsshm_read_line _ "$(lsshm_t 'Press Enter to continue... ')" || true
}

# Run a command from a menu without aborting the loop under set -e.
lsshm_menu_try() {
    "$@" || true
    return 0
}

# Interactive menu action: run (ignore failure/cancel), then pause in CLI mode.
lsshm_menu_action() {
    "$@" || true
    if ! lsshm_uses_dialog_ui; then
        lsshm_pause
    fi
    return 0
}

# -----------------------------------------------------------------------------
# Temporary files (tracked and cleaned on exit)
# -----------------------------------------------------------------------------
LSSHM_TMPFILES=()
# Side-channel list so temps created inside $(...) still get cleaned on EXIT.
LSSHM_TMPTRACK=""

lsshm_mktemp() {
    # Usage: lsshm_mktemp [persist]
    # "persist" skips cleanup tracking (rollback helper scripts must survive EXIT).
    local mode="${1:-}" tmp
    tmp="$(mktemp "${TMPDIR:-/tmp}/lsshm.XXXXXX")" || lsshm_die 'Unable to create a temporary file.'
    if [ "$mode" != "persist" ]; then
        LSSHM_TMPFILES+=("$tmp")
        if [ -n "${LSSHM_TMPTRACK:-}" ]; then
            printf '%s\n' "$tmp" >>"$LSSHM_TMPTRACK" 2>/dev/null || true
        fi
    fi
    printf '%s' "$tmp"
}

lsshm_cleanup() {
    local f
    for f in "${LSSHM_TMPFILES[@]:-}"; do
        [ -n "$f" ] && rm -f "$f" 2>/dev/null || true
    done
    if [ -n "${LSSHM_TMPTRACK:-}" ] && [ -f "$LSSHM_TMPTRACK" ]; then
        while IFS= read -r f || [ -n "$f" ]; do
            [ -n "$f" ] && rm -f "$f" 2>/dev/null || true
        done <"$LSSHM_TMPTRACK"
        rm -f "$LSSHM_TMPTRACK" 2>/dev/null || true
    fi
}

# -----------------------------------------------------------------------------
# Small utilities
# -----------------------------------------------------------------------------
lsshm_have() { command -v "$1" >/dev/null 2>&1; }

lsshm_yesno_label() {
    case "$1" in
        yes|true|on|1) lsshm_t 'yes' ;;
        no|false|off|0) lsshm_t 'no' ;;
        "") lsshm_t 'not set' ;;
        *) printf '%s' "$1" ;;
    esac
}

# Ensure the runtime directories exist.
lsshm_ensure_dirs() {
    local d
    for d in "$LSSHM_CONFIG_DIR" "$LSSHM_DATA_DIR" "$LSSHM_STATE_DIR" \
             "$LSSHM_CACHE_DIR" "$LSSHM_BACKUP_DIR"; do
        [ -d "$d" ] || mkdir -p "$d" 2>/dev/null || true
    done
    # Init temp tracking file once state dir is available (survives subshells).
    if [ -z "${LSSHM_TMPTRACK:-}" ] && [ -d "$LSSHM_STATE_DIR" ]; then
        LSSHM_TMPTRACK="$LSSHM_STATE_DIR/tmpfiles.$$"
        : >"$LSSHM_TMPTRACK" 2>/dev/null || LSSHM_TMPTRACK=""
    fi
}

# ===== src/i18n.sh =====================================================
# shellcheck shell=bash
# =============================================================================
# i18n.sh - internationalization (message catalogs + language selection)
# =============================================================================
# LSSHM source strings are written in English (the msgid). Translations are
# stored in per-language associative arrays keyed by the English msgid.
# A missing translation falls back to English, so the tool is always usable
# even with an incomplete catalog.
#
# Adding a language:
#   1. Add its code to LSSHM_LANGS and a native name in lsshm_lang_native_name.
#   2. Declare LSSHM_MSG_<code> and populate it below (mirror the fr catalog).
#   3. Handle it in lsshm_t and lsshm_detect_lang.
# This module must be sourced (or concatenated) right after common.sh.

# Supported language codes (space separated). English is the built-in default.
LSSHM_LANGS="en fr es"
LSSHM_LANG="${LSSHM_LANG:-en}"

declare -A LSSHM_MSG_fr
declare -A LSSHM_MSG_es

# -----------------------------------------------------------------------------
# Lookup helpers
# -----------------------------------------------------------------------------
# lsshm_t MSGID -> prints the translated string (no newline). English falls
# back to the msgid itself, as does any missing translation.
lsshm_t() {
    local msgid="$1" out=""
    case "$LSSHM_LANG" in
        fr) out="${LSSHM_MSG_fr[$msgid]-}" ;;
        es) out="${LSSHM_MSG_es[$msgid]-}" ;;
        *)  out="" ;;
    esac
    if [ -n "$out" ]; then
        printf '%s' "$out"
    else
        printf '%s' "$msgid"
    fi
}

# lsshm_tf MSGID [ARGS...] -> printf the translated format string with ARGS.
lsshm_tf() {
    local fmt; fmt="$(lsshm_t "$1")"; shift
    # shellcheck disable=SC2059
    printf "$fmt" "$@"
}

# lsshm_out MSGID [ARGS...] -> like lsshm_tf but appends a newline (stdout).
lsshm_out() {
    local fmt; fmt="$(lsshm_t "$1")"; shift
    # shellcheck disable=SC2059
    printf "$fmt\n" "$@"
}

# -----------------------------------------------------------------------------
# Language codes and names
# -----------------------------------------------------------------------------
lsshm_lang_is_supported() {
    case " $LSSHM_LANGS " in
        *" $1 "*) return 0 ;;
        *) return 1 ;;
    esac
}

lsshm_lang_native_name() {
    case "$1" in
        en) printf 'English' ;;
        fr) printf 'Français' ;;
        es) printf 'Español' ;;
        *)  printf '%s' "$1" ;;
    esac
}

# Detect the preferred language from the environment locale.
lsshm_detect_lang() {
    local l="${LC_ALL:-${LC_MESSAGES:-${LANG:-}}}"
    l="${l%%.*}"       # drop encoding (fr_FR.UTF-8 -> fr_FR)
    l="${l%%@*}"       # drop modifier
    l="${l%%_*}"       # drop territory (fr_FR -> fr)
    l="$(printf '%s' "$l" | tr '[:upper:]' '[:lower:]')"
    case "$l" in
        fr) printf 'fr' ;;
        es) printf 'es' ;;
        en) printf 'en' ;;
        *)  printf 'en' ;;
    esac
}

# Resolve the active language: explicit override > config > locale detection.
lsshm_i18n_init() {
    local want=""
    if [ -n "${LSSHM_LANG_OVERRIDE:-}" ]; then
        want="$LSSHM_LANG_OVERRIDE"
    elif [ -n "${LSSHM_CFG_LANG:-}" ]; then
        want="$LSSHM_CFG_LANG"
    else
        want="$(lsshm_detect_lang)"
    fi
    if lsshm_lang_is_supported "$want"; then
        LSSHM_LANG="$want"
    else
        LSSHM_LANG="en"
    fi
    export LSSHM_LANG
}

# True when the user has never chosen a language (no value stored in config).
lsshm_i18n_configured() {
    [ -n "${LSSHM_CFG_LANG:-}" ]
}

# Interactive language picker. Preselects the detected system language.
# Persists the choice to the configuration file when possible.
lsshm_i18n_choose() {
    local detected def i=0 code choice
    detected="$(lsshm_detect_lang)"

    printf '\n' >&2
    printf 'Language / Langue / Idioma:\n' >&2
    local -a codes=()
    for code in $LSSHM_LANGS; do
        i=$((i + 1))
        codes+=("$code")
        printf '  %d. %s\n' "$i" "$(lsshm_lang_native_name "$code")" >&2
        [ "$code" = "$detected" ] && def="$i"
    done
    def="${def:-1}"

    # || true: a failed prompt under set -e must not abort LSSHM.
    choice="$(lsshm_prompt "Choice / Choix / Elección" "$def" || true)"
    [ -n "$choice" ] || choice="$def"

    local picked=""
    if [[ "$choice" =~ ^[0-9]+$ ]] && [ "$choice" -ge 1 ] && [ "$choice" -le "${#codes[@]}" ]; then
        picked="${codes[$((choice - 1))]}"
    elif lsshm_lang_is_supported "$choice"; then
        picked="$choice"
    else
        picked="$detected"
    fi

    LSSHM_LANG="$picked"
    export LSSHM_LANG
    LSSHM_CFG_LANG="$picked"
    lsshm_config_set language "$picked" 2>/dev/null || true
    lsshm_out 'Language set to: %s' "$(lsshm_lang_native_name "$picked")"
}

