# ===== src/platform.sh =================================================
# shellcheck shell=bash
# =============================================================================
# platform.sh - detect distribution, package manager, service manager, virt
# =============================================================================

lsshm_detect_platform() {
    LSSHM_OS_ID="unknown"
    LSSHM_OS_NAME="Unknown"
    LSSHM_OS_LIKE=""
    LSSHM_OS_VERSION=""

    if [ -r /etc/os-release ]; then
        # shellcheck disable=SC1091
        . /etc/os-release
        LSSHM_OS_ID="${ID:-unknown}"
        LSSHM_OS_NAME="${PRETTY_NAME:-${NAME:-Unknown}}"
        LSSHM_OS_LIKE="${ID_LIKE:-}"
        LSSHM_OS_VERSION="${VERSION_ID:-}"
    fi

    LSSHM_PKG_MGR="$(lsshm_detect_pkg_mgr)"
    LSSHM_SVC_MGR="$(lsshm_detect_svc_mgr)"
    LSSHM_HAS_SYSTEMD=0
    [ "$LSSHM_SVC_MGR" = "systemd" ] && LSSHM_HAS_SYSTEMD=1

    LSSHM_VIRT="$(lsshm_detect_virt)"
    LSSHM_SSHD_BIN="$(lsshm_detect_sshd_bin)"
    LSSHM_SSH_SERVICE="$(lsshm_detect_ssh_service)"
}

lsshm_detect_pkg_mgr() {
    if lsshm_have apt-get; then printf 'apt'
    elif lsshm_have apk; then printf 'apk'
    elif lsshm_have dnf; then printf 'dnf'
    elif lsshm_have yum; then printf 'yum'
    elif lsshm_have pacman; then printf 'pacman'
    elif lsshm_have zypper; then printf 'zypper'
    else printf 'unknown'
    fi
}

lsshm_detect_svc_mgr() {
    if lsshm_have systemctl && [ -d /run/systemd/system ]; then printf 'systemd'
    elif lsshm_have rc-service; then printf 'openrc'
    elif lsshm_have service; then printf 'sysv'
    else printf 'unknown'
    fi
}

lsshm_detect_virt() {
    if lsshm_have systemd-detect-virt; then
        systemd-detect-virt 2>/dev/null || printf 'none'
    elif [ -f /run/systemd/container ]; then
        cat /run/systemd/container 2>/dev/null || printf 'container'
    elif grep -qa 'container=lxc' /proc/1/environ 2>/dev/null; then
        printf 'lxc'
    else
        printf 'unknown'
    fi
}

lsshm_detect_sshd_bin() {
    local candidate
    for candidate in /usr/sbin/sshd /usr/bin/sshd /sbin/sshd; do
        [ -x "$candidate" ] && { printf '%s' "$candidate"; return 0; }
    done
    if lsshm_have sshd; then
        command -v sshd
        return 0
    fi
    printf ''
}

lsshm_detect_ssh_service() {
    # Debian/Ubuntu use "ssh", most RPM/Arch use "sshd".
    case "$LSSHM_OS_ID" in
        debian|ubuntu|raspbian|linuxmint|pop) printf 'ssh' ;;
        *) printf 'sshd' ;;
    esac
}

lsshm_platform_summary() {
    lsshm_out 'Distribution        : %s' "$LSSHM_OS_NAME"
    lsshm_out 'Identifier          : %s' "$LSSHM_OS_ID ${LSSHM_OS_VERSION:+($LSSHM_OS_VERSION)}"
    lsshm_out 'Package manager     : %s' "$LSSHM_PKG_MGR"
    lsshm_out 'Service manager     : %s' "$LSSHM_SVC_MGR"
    lsshm_out 'systemd             : %s' "$([ "$LSSHM_HAS_SYSTEMD" = 1 ] && lsshm_t present || lsshm_t absent)"
    lsshm_out 'Virtualization      : %s' "$LSSHM_VIRT"
    lsshm_out 'sshd binary         : %s' "${LSSHM_SSHD_BIN:-$(lsshm_t 'not detected')}"
    lsshm_out 'SSH service         : %s' "$LSSHM_SSH_SERVICE"
}

# Is the current distribution supported for full management in this version?
lsshm_platform_is_primary() {
    case "$LSSHM_OS_ID" in
        debian) return 0 ;;
        ubuntu|raspbian|linuxmint|pop) return 0 ;;
        *)
            case " $LSSHM_OS_LIKE " in
                *debian*) return 0 ;;
                *) return 1 ;;
            esac
            ;;
    esac
}

# ===== src/privileges.sh ===============================================
# shellcheck shell=bash
# =============================================================================
# privileges.sh - privilege elevation and calling-user resolution
# =============================================================================

lsshm_init_privileges() {
    LSSHM_EUID="$(id -u)"
    LSSHM_IS_ROOT=0
    [ "$LSSHM_EUID" = "0" ] && LSSHM_IS_ROOT=1

    # Default target for personal SSH files until resolve_target_user runs:
    # sudo → original user; direct root → root; otherwise the current user.
    LSSHM_CALLING_USER="${LSSHM_TARGET_USER:-${SUDO_USER:-${USER:-$(id -un)}}}"
    if [ -z "${LSSHM_TARGET_USER:-}" ] && [ "$LSSHM_IS_ROOT" = "1" ] \
        && { [ -z "${SUDO_USER:-}" ] || [ "$SUDO_USER" = "root" ]; }; then
        LSSHM_CALLING_USER="root"
    fi

    if lsshm_have sudo && [ "$LSSHM_IS_ROOT" = "0" ]; then
        LSSHM_SUDO="sudo"
    else
        LSSHM_SUDO=""
    fi
    # Set after a successful sudo -v / privileged auth in this process.
    LSSHM_SUDO_PRIMED="${LSSHM_SUDO_PRIMED:-0}"
}

# Home directory of a given user.
lsshm_user_home() {
    local user="$1" home
    home="$(getent passwd "$user" 2>/dev/null | cut -d: -f6)"
    if [ -z "$home" ]; then
        if [ "$user" = "${USER:-}" ]; then
            home="$HOME"
        else
            home="/home/$user"
        fi
    fi
    printf '%s' "$home"
}

# The .ssh directory for the managed (calling) user.
lsshm_target_ssh_dir() {
    printf '%s/.ssh' "$(lsshm_user_home "$LSSHM_CALLING_USER")"
}

# Expand a leading ~/ using the managed user's home (not the process $HOME).
lsshm_expand_user_path() {
    local path="$1" user="${2:-$LSSHM_CALLING_USER}"
    if [ "${path#~/}" != "$path" ]; then
        printf '%s/%s' "$(lsshm_user_home "$user")" "${path#~/}"
    else
        printf '%s' "$path"
    fi
}

# True if a non-interactive sudo would succeed (cached credentials).
lsshm_sudo_ready() {
    [ "$LSSHM_IS_ROOT" = "1" ] && return 0
    [ -n "${LSSHM_SUDO:-}" ] || return 1
    sudo -n true >/dev/null 2>&1
}

# Ask for the sudo password at most once per session (when needed).
lsshm_sudo_ensure() {
    if [ "$LSSHM_IS_ROOT" = "1" ]; then
        return 0
    fi
    if [ -z "${LSSHM_SUDO:-}" ]; then
        lsshm_error 'This operation requires root privileges, but sudo was not found.'
        return 1
    fi
    if lsshm_sudo_ready; then
        LSSHM_SUDO_PRIMED=1
        return 0
    fi
    if ! lsshm_is_interactive || [ ! -t 0 ]; then
        lsshm_error 'sudo authentication required (non-interactive session).'
        return 1
    fi
    lsshm_note 'Administrator authentication (sudo) — once for this session.'
    if sudo -v; then
        LSSHM_SUDO_PRIMED=1
        return 0
    fi
    lsshm_error 'sudo authentication failed.'
    return 1
}

# Run a command that requires root. Uses sudo only when necessary.
# Authenticates once via lsshm_sudo_ensure, then reuses the sudo ticket.
lsshm_run_privileged() {
    if [ "$LSSHM_IS_ROOT" = "1" ]; then
        "$@"
    elif [ -n "$LSSHM_SUDO" ]; then
        lsshm_sudo_ensure || return 1
        # Do not fall back to an interactive sudo on command failure (that would
        # re-prompt for the password when sshd -t / systemctl simply return 1).
        if lsshm_sudo_ready; then
            sudo -n "$@"
        else
            sudo "$@"
        fi
    else
        lsshm_error 'This operation requires root privileges, but sudo was not found.'
        return 1
    fi
}

# Run several shell commands under a single sudo (one password prompt max).
# Usage: lsshm_run_privileged_sh 'cmd1 && cmd2'
lsshm_run_privileged_sh() {
    local script="$1"
    if [ "$LSSHM_IS_ROOT" = "1" ]; then
        sh -c "$script"
    elif [ -n "$LSSHM_SUDO" ]; then
        lsshm_sudo_ensure || return 1
        if lsshm_sudo_ready; then
            sudo -n sh -c "$script"
        else
            sudo sh -c "$script"
        fi
    else
        lsshm_error 'This operation requires root privileges, but sudo was not found.'
        return 1
    fi
}

# True if we can obtain root (already root or sudo available).
lsshm_can_elevate() {
    [ "$LSSHM_IS_ROOT" = "1" ] || [ -n "$LSSHM_SUDO" ]
}

lsshm_require_root() {
    if ! lsshm_can_elevate; then
        lsshm_die 'Privileged operation not possible: run LSSHM as root or install sudo.'
    fi
}

# Validate and set the user whose personal SSH files are managed.
lsshm_set_target_user() {
    local user="$1"
    if [ -z "$user" ]; then
        lsshm_error 'Empty username.'
        return 1
    fi
    if ! lsshm_user_exists "$user"; then
        lsshm_error 'Unknown user: %s' "$user"
        return 1
    fi
    LSSHM_CALLING_USER="$user"
    LSSHM_TARGET_USER="$user"
    lsshm_ok 'Managed user: %s (%s/.ssh)' "$LSSHM_CALLING_USER" "$(lsshm_user_home "$LSSHM_CALLING_USER")"
}

# Ensure ~/.ssh exists with correct ownership for a target user (root admin case).
lsshm_ensure_user_ssh_dir() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local home ssh_dir uid gid
    home="$(lsshm_user_home "$user")"
    ssh_dir="$home/.ssh"
    uid="$(id -u "$user" 2>/dev/null || echo 0)"
    gid="$(id -g "$user" 2>/dev/null || echo 0)"

    if [ "$LSSHM_IS_ROOT" = "1" ]; then
        mkdir -p "$ssh_dir"
        chmod 700 "$ssh_dir"
        chown "$uid:$gid" "$ssh_dir"
    elif mkdir -p "$ssh_dir" 2>/dev/null; then
        chmod 700 "$ssh_dir" 2>/dev/null || true
    else
        lsshm_run_privileged mkdir -p "$ssh_dir"
        lsshm_run_privileged chmod 700 "$ssh_dir"
        lsshm_run_privileged chown "$uid:$gid" "$ssh_dir"
    fi
}

# chown paths to a login user when we are root (no-op otherwise).
lsshm_chown_user() {
    local user="$1"
    shift
    [ "$LSSHM_IS_ROOT" = "1" ] || return 0
    [ "$#" -gt 0 ] || return 0
    local uid gid
    uid="$(id -u "$user" 2>/dev/null || echo 0)"
    gid="$(id -g "$user" 2>/dev/null || echo 0)"
    chown "$uid:$gid" "$@"
}

# Interactive picker: numbered login users (+ root), or typed name.
lsshm_pick_target_user() {
    local default="${1:-$LSSHM_CALLING_USER}"
    local -a names=()
    local name uid home i=0 user_list="" choice=""

    user_list="$(lsshm_users_list 2>/dev/null)" || user_list=""

    printf '\n' >&2
    lsshm_out 'Available local users:' >&2
    while IFS=: read -r name uid home || [ -n "$name" ]; do
        [ -n "$name" ] || continue
        i=$((i + 1))
        names+=("$name")
        printf '  %d. %-16s uid=%-6s %s\n' "$i" "$name" "$uid" "$home" >&2
    done <<EOF
$user_list
EOF

    if [ "$i" -eq 0 ]; then
        lsshm_error 'No local user detected.'
        return 1
    fi

    # || true: under set -e, a failed prompt inside $(...) must not abort LSSHM.
    choice="$(lsshm_prompt "$(lsshm_t 'User to manage (number or name)')" "$default" || true)"
    [ -n "$choice" ] || return 1

    if [[ "$choice" =~ ^[0-9]+$ ]]; then
        if [ "$choice" -lt 1 ] || [ "$choice" -gt "${#names[@]}" ]; then
            lsshm_error 'Number out of range (1-%s).' "${#names[@]}"
            return 1
        fi
        choice="${names[$((choice - 1))]}"
    fi

    lsshm_set_target_user "$choice"
}

# Resolve which user's personal SSH files to manage (keys, access, hosts).
lsshm_resolve_target_user() {
    # Explicit --user always wins.
    if [ -n "${LSSHM_TARGET_USER:-}" ]; then
        if ! lsshm_user_exists "$LSSHM_TARGET_USER"; then
            lsshm_die 'Unknown user: %s' "$LSSHM_TARGET_USER"
        fi
        LSSHM_CALLING_USER="$LSSHM_TARGET_USER"
        return 0
    fi

    # Non-interactive defaults: sudo → calling user; direct root → root.
    if ! lsshm_is_interactive; then
        if [ "$LSSHM_IS_ROOT" = "1" ]; then
            if [ -n "${SUDO_USER:-}" ] && [ "$SUDO_USER" != "root" ]; then
                LSSHM_CALLING_USER="$SUDO_USER"
            else
                LSSHM_CALLING_USER="root"
            fi
        fi
        return 0
    fi

    # Interactive privileged session: pick whose personal SSH files to manage.
    if [ "$LSSHM_IS_ROOT" = "1" ]; then
        if [ -n "${SUDO_USER:-}" ] && [ "$SUDO_USER" != "root" ]; then
            # Elevated via sudo: preselect the calling user; option 2 can pick
            # root or any other account.
            printf '\n'; lsshm_out '%s is running with sudo.' "$LSSHM_NAME"
            lsshm_out 'Calling user   : %s' "$SUDO_USER"
            lsshm_out 'Privileged user: root'; printf '\n'
            lsshm_out 'Whose personal SSH files should be managed?'
            lsshm_out '  1. %s (recommended)' "$SUDO_USER"
            lsshm_out '  2. Choose another user'
            local choice=""
            choice="$(lsshm_prompt "$(lsshm_t 'Choice')" '1' || true)"
            case "$choice" in
                2) lsshm_pick_target_user "$SUDO_USER" || LSSHM_CALLING_USER="$SUDO_USER" ;;
                *) lsshm_set_target_user "$SUDO_USER" || LSSHM_CALLING_USER="$SUDO_USER" ;;
            esac
        else
            # Direct root login: preselect root.
            printf '\n'; lsshm_out '%s is running as root.' "$LSSHM_NAME"
            lsshm_out "You can manage another user's SSH (keys, access, hosts)."; printf '\n'
            lsshm_out 'Whose personal SSH files should be managed?'
            lsshm_out '  1. %s (recommended)' "root"
            lsshm_out '  2. Choose another user'
            local choice=""
            choice="$(lsshm_prompt "$(lsshm_t 'Choice')" '1' || true)"
            case "$choice" in
                2) lsshm_pick_target_user "root" || lsshm_set_target_user "root" || true ;;
                *) lsshm_set_target_user "root" || true ;;
            esac
        fi
    fi
}

# ===== src/backup.sh ===================================================
# shellcheck shell=bash
# =============================================================================
# backup.sh - backup and restore of managed SSH files
# =============================================================================
# Backups are stored under $LSSHM_BACKUP_DIR as timestamped tar archives.

lsshm_backup_timestamp() { date '+%Y%m%d-%H%M%S'; }

# Copy a single file into a timestamped backup set, preserving path.
# Usage: lsshm_backup_file /etc/ssh/sshd_config [label]
lsshm_backup_file() {
    local src="$1" label="${2:-file}"
    [ -e "$src" ] || return 0
    lsshm_ensure_dirs
    local stamp; stamp="$(lsshm_backup_timestamp)"
    local dest="$LSSHM_BACKUP_DIR/${stamp}-${label}"
    mkdir -p "$dest" 2>/dev/null || true
    local base; base="$(basename "$src")"
    if [ -r "$src" ]; then
        cp -a "$src" "$dest/$base" 2>/dev/null || \
            lsshm_run_privileged cp -a "$src" "$dest/$base"
    else
        lsshm_run_privileged cp -a "$src" "$dest/$base"
    fi
    printf '%s' "$dest/$base"
    lsshm_log INFO "Backup of $src -> $dest/$base"
}

# Full backup of the SSH server configuration tree.
lsshm_backup_server_config() {
    lsshm_ensure_dirs
    local stamp; stamp="$(lsshm_backup_timestamp)"
    local archive="$LSSHM_BACKUP_DIR/${stamp}-sshd-config.tar.gz"
    local tmp; tmp="$(lsshm_mktemp)"
    {
        [ -f /etc/ssh/sshd_config ] && printf '/etc/ssh/sshd_config\n'
        [ -d /etc/ssh/sshd_config.d ] && printf '/etc/ssh/sshd_config.d\n'
    } >"$tmp"
    if [ ! -s "$tmp" ]; then
        lsshm_warn 'No server configuration to back up.'
        return 1
    fi
    if lsshm_run_privileged tar -czf "$archive" -T "$tmp" 2>/dev/null; then
        # When stdout is captured (rollback), emit only the path.
        # Interactively, show a human message instead.
        if [ -t 1 ]; then
            lsshm_ok 'Backup created: %s' "$archive"
        else
            printf '%s' "$archive"
        fi
        return 0
    fi
    lsshm_error 'Server configuration backup failed.'
    return 1
}

# Backup a user's authorized_keys.
lsshm_backup_authorized_keys() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local home; home="$(lsshm_user_home "$user")"
    lsshm_backup_file "$home/.ssh/authorized_keys" "authkeys-$user"
}

lsshm_backup_list() {
    lsshm_ensure_dirs
    if [ -z "$(ls -A "$LSSHM_BACKUP_DIR" 2>/dev/null)" ]; then
        lsshm_info 'No backups recorded.'
        return 0
    fi
    lsshm_info 'Backups in %s:' "$LSSHM_BACKUP_DIR"
    local entry
    for entry in "$LSSHM_BACKUP_DIR"/*; do
        [ -e "$entry" ] || continue
        printf '  %s\n' "$(basename "$entry")"
    done
}

# Restore the SSH server configuration from an archive.
lsshm_backup_restore_server() {
    local archive="$1"
    if [ ! -f "$archive" ]; then
        # Allow passing just the basename.
        archive="$LSSHM_BACKUP_DIR/$archive"
    fi
    [ -f "$archive" ] || lsshm_die 'Backup archive not found: %s' "$1"
    lsshm_warn 'Restoring server configuration from: %s' "$archive"
    lsshm_confirm "$(lsshm_t 'Confirm the restore?')" no || { lsshm_info 'Cancelled.'; return 1; }
    if lsshm_run_privileged tar -xzf "$archive" -C / ; then
        lsshm_ok 'Configuration restored.'
        lsshm_server_config_test && lsshm_server_reload
    else
        lsshm_error 'Restore failed.'
        return 1
    fi
}

lsshm_backup_menu() {
    while true; do
        local choice="" pick_ret=0
        if lsshm_uses_dialog_ui; then
            choice="$(lsshm_dialog_backup_menu)" || pick_ret=$?
            [ "$pick_ret" -ne 0 ] && break
        else
            clear 2>/dev/null || true
            lsshm_header
            lsshm_out 'Backup and restore'; printf '\n'
            lsshm_out '  1. Back up the SSH server configuration'
            lsshm_out '  2. Back up authorized keys (authorized_keys)'
            lsshm_out '  3. List backups'
            lsshm_out '  4. Restore a server configuration'
            lsshm_out '  5. Back'
            choice="$(lsshm_prompt "$(lsshm_t 'Choice')" '5' || true)"
        fi
        case "$choice" in
            1) lsshm_ui_run "$(lsshm_t 'SSH server backup')" lsshm_backup_server_config ;;
            2) lsshm_ui_run "$(lsshm_t 'authorized_keys backup')" lsshm_backup_authorized_keys "$LSSHM_CALLING_USER" ;;
            3) lsshm_ui_run "$(lsshm_t 'Available backups')" lsshm_backup_list ;;
            4)
                if lsshm_uses_dialog_ui; then
                    lsshm_menu_try lsshm_ui_show "$(lsshm_t 'Backups')" lsshm_backup_list
                else
                    lsshm_menu_try lsshm_backup_list
                fi
                local a=""
                a="$(lsshm_prompt "$(lsshm_t 'Archive name to restore')" '' || true)"
                if [ -n "$a" ]; then
                    lsshm_menu_try lsshm_backup_restore_server "$a"
                fi
                lsshm_uses_dialog_ui || lsshm_pause
                ;;
            5|q|Q) break ;;
            *) lsshm_warn 'Invalid choice.'; lsshm_uses_dialog_ui || lsshm_pause ;;
        esac
    done
}

# ===== src/server.sh ===================================================
# shellcheck shell=bash
# =============================================================================
# server.sh - OpenSSH server service management
# =============================================================================

lsshm_server_is_installed() {
    [ -n "${LSSHM_SSHD_BIN:-}" ] && [ -x "$LSSHM_SSHD_BIN" ]
}

# --- service actions ---------------------------------------------------------

lsshm_server_action() {
    # lsshm_server_action start|stop|restart|reload|enable|disable
    local action="$1"
    case "$LSSHM_SVC_MGR" in
        systemd)
            lsshm_run_privileged systemctl "$action" "$LSSHM_SSH_SERVICE"
            ;;
        openrc)
            case "$action" in
                enable)  lsshm_run_privileged rc-update add "$LSSHM_SSH_SERVICE" default ;;
                disable) lsshm_run_privileged rc-update del "$LSSHM_SSH_SERVICE" default ;;
                reload)  lsshm_run_privileged rc-service "$LSSHM_SSH_SERVICE" reload \
                             || lsshm_run_privileged rc-service "$LSSHM_SSH_SERVICE" restart ;;
                *)       lsshm_run_privileged rc-service "$LSSHM_SSH_SERVICE" "$action" ;;
            esac
            ;;
        sysv)
            case "$action" in
                enable|disable)
                    lsshm_warn 'Automatic enable/disable is not handled for SysV here.'
                    return 1 ;;
                *) lsshm_run_privileged service "$LSSHM_SSH_SERVICE" "$action" ;;
            esac
            ;;
        *)
            lsshm_error "Unknown service manager: cannot run '%s'." "$action"
            return 1
            ;;
    esac
}

lsshm_server_start()   { lsshm_server_action start   && lsshm_ok 'SSH service started.'; }
lsshm_server_stop()    { lsshm_server_action stop    && lsshm_ok 'SSH service stopped.'; }
lsshm_server_restart() { lsshm_server_action restart && lsshm_ok 'SSH service restarted.'; }
lsshm_server_enable()  { lsshm_server_action enable  && lsshm_ok 'Automatic startup enabled.'; }
lsshm_server_disable() { lsshm_server_action disable && lsshm_ok 'Automatic startup disabled.'; }

# Reload preferred over restart; validate config first.
lsshm_server_reload() {
    if ! lsshm_server_config_test; then
        lsshm_error 'Invalid configuration: reload cancelled.'
        return 1
    fi
    if lsshm_server_action reload; then
        lsshm_server_config_invalidate_cache
        lsshm_ok 'SSH service reloaded.'
    else
        return 1
    fi
}

# --- status ------------------------------------------------------------------

lsshm_server_is_active() {
    case "$LSSHM_SVC_MGR" in
        systemd) systemctl is-active --quiet "$LSSHM_SSH_SERVICE" ;;
        openrc)  rc-service "$LSSHM_SSH_SERVICE" status >/dev/null 2>&1 ;;
        sysv)    service "$LSSHM_SSH_SERVICE" status >/dev/null 2>&1 ;;
        *)       lsshm_server_port_listening ;;
    esac
}

lsshm_server_is_enabled() {
    case "$LSSHM_SVC_MGR" in
        systemd) systemctl is-enabled --quiet "$LSSHM_SSH_SERVICE" 2>/dev/null ;;
        openrc)  rc-update show default 2>/dev/null | grep -qw "$LSSHM_SSH_SERVICE" ;;
        *)       return 1 ;;
    esac
}

# Is the configured SSH port actually listening?
lsshm_server_port_listening() {
    local port; port="$(lsshm_server_config_effective_value port)"
    port="${port:-22}"
    if lsshm_have ss; then
        ss -ltn 2>/dev/null | grep -Eq "[:.]${port}[[:space:]]"
    elif lsshm_have netstat; then
        netstat -ltn 2>/dev/null | grep -Eq "[:.]${port}[[:space:]]"
    else
        return 2
    fi
}

lsshm_server_status() {
    if ! lsshm_server_is_installed; then
        lsshm_warn 'OpenSSH Server is not installed (sshd binary not found).'
        return 0
    fi
    local active enabled port rootlogin passauth pubkey
    if lsshm_server_is_active; then active="$(lsshm_t active)"; else active="$(lsshm_t inactive)"; fi
    if lsshm_server_is_enabled; then enabled="$(lsshm_t yes)"; else enabled="$(lsshm_t no)"; fi
    port="$(lsshm_server_config_effective_value port)"; port="${port:-22}"
    rootlogin="$(lsshm_server_config_effective_value permitrootlogin)"
    passauth="$(lsshm_server_config_effective_value passwordauthentication)"
    pubkey="$(lsshm_server_config_effective_value pubkeyauthentication)"

    lsshm_out 'SSH server status : %s' "$active"
    lsshm_out 'Auto-start        : %s' "$enabled"
    lsshm_out 'Port              : %s' "$port"
    lsshm_out 'Root access       : %s' "$(lsshm_rootlogin_label "$rootlogin")"
    lsshm_out 'Password auth.    : %s' "$(lsshm_yesno_label "$passauth")"
    lsshm_out 'Key auth.         : %s' "$(lsshm_yesno_label "$pubkey")"
}

# --- installation ------------------------------------------------------------

lsshm_server_install() {
    if lsshm_server_is_installed; then
        lsshm_ok 'OpenSSH Server is already installed: %s' "$LSSHM_SSHD_BIN"
        return 0
    fi
    lsshm_info 'Installing OpenSSH Server...'
    lsshm_require_root
    case "$LSSHM_PKG_MGR" in
        apt)
            lsshm_run_privileged apt-get update && \
            lsshm_run_privileged apt-get install -y openssh-server ;;
        apk)
            lsshm_run_privileged apk add openssh ;;
        dnf)
            lsshm_run_privileged dnf install -y openssh-server ;;
        yum)
            lsshm_run_privileged yum install -y openssh-server ;;
        pacman)
            lsshm_run_privileged pacman -Sy --noconfirm openssh ;;
        zypper)
            lsshm_run_privileged zypper install -y openssh ;;
        *)
            lsshm_error 'Unsupported package manager: %s' "$LSSHM_PKG_MGR"
            return 1 ;;
    esac
    # Refresh detection.
    LSSHM_SSHD_BIN="$(lsshm_detect_sshd_bin)"
    if lsshm_server_is_installed; then
        lsshm_ok 'OpenSSH Server installed.'
        lsshm_server_action enable || true
        lsshm_server_action start  || true
    else
        lsshm_error 'The installation appears to have failed.'
        return 1
    fi
}

lsshm_server_logs() {
    local lines="${1:-40}"
    if [ "$LSSHM_SVC_MGR" = "systemd" ] && lsshm_have journalctl; then
        lsshm_run_privileged journalctl -u "$LSSHM_SSH_SERVICE" -n "$lines" --no-pager
    elif [ -f /var/log/auth.log ]; then
        lsshm_run_privileged tail -n "$lines" /var/log/auth.log
    elif [ -f /var/log/secure ]; then
        lsshm_run_privileged tail -n "$lines" /var/log/secure
    else
        lsshm_warn 'No SSH log source detected.'
        return 1
    fi
}

# ===== src/server_config.sh ============================================
# shellcheck shell=bash
# =============================================================================
# server_config.sh - sshd_config parsing, effective values, managed drop-in
# =============================================================================

LSSHM_SSHD_CONFIG="/etc/ssh/sshd_config"
LSSHM_MANAGED_CONF="/etc/ssh/sshd_config.d/00-lsshm.conf"

LSSHM_MANAGED_HEADER="# Managed by LSSHM
# Local SSH Manager
# Manual changes may be overwritten."

# --- validation --------------------------------------------------------------

# sshd -t : validate configuration. Returns non-zero on error.
lsshm_server_config_test() {
    if [ -z "${LSSHM_SSHD_BIN:-}" ]; then
        lsshm_warn 'sshd binary not found: validation not possible.'
        return 0
    fi
    local out
    if out="$(lsshm_run_privileged "$LSSHM_SSHD_BIN" -t 2>&1)"; then
        return 0
    fi
    lsshm_error 'sshd -t reported an error:'
    printf '%s\n' "$out" >&2
    return 1
}

lsshm_server_config_cache_file() {
    printf '%s/sshd-T.cache' "${LSSHM_CACHE_DIR:-${TMPDIR:-/tmp}}"
}

# Invalidate the cached sshd -T dump (call after config changes).
# File-backed so the cache survives dump="$(lsshm_server_config_dump)" subshells.
lsshm_server_config_invalidate_cache() {
    LSSHM_SSHD_T_CACHE=""
    LSSHM_SSHD_T_CACHED=0
    rm -f "$(lsshm_server_config_cache_file)" 2>/dev/null || true
}

# sshd -T : dump the effective configuration (cached).
# Never prompts for a sudo password: uses an existing ticket (sudo -n) or fails
# so the status panel / menu can open without asking for admin credentials.
# Pass "refresh" to force a new privileged dump (may prompt once via sudo -v).
lsshm_server_config_dump() {
    local mode="${1:-}" cache_file dump=""
    [ -n "${LSSHM_SSHD_BIN:-}" ] || return 1
    cache_file="$(lsshm_server_config_cache_file)"

    if [ "$mode" = "refresh" ]; then
        lsshm_server_config_invalidate_cache
        if [ "$LSSHM_IS_ROOT" != "1" ] && [ -n "${LSSHM_SUDO:-}" ]; then
            lsshm_sudo_ensure || return 1
        fi
    fi

    if [ -f "$cache_file" ]; then
        cat "$cache_file"
        return 0
    fi
    if [ "${LSSHM_SSHD_T_CACHED:-0}" = "1" ] && [ -n "${LSSHM_SSHD_T_CACHE:-}" ]; then
        printf '%s\n' "$LSSHM_SSHD_T_CACHE"
        return 0
    fi

    if [ "$LSSHM_IS_ROOT" = "1" ]; then
        dump="$("$LSSHM_SSHD_BIN" -T 2>/dev/null)" || return 1
    elif [ -n "${LSSHM_SUDO:-}" ]; then
        # Read-only: never trigger a password prompt here.
        dump="$(sudo -n "$LSSHM_SSHD_BIN" -T 2>/dev/null)" || return 1
    else
        dump="$("$LSSHM_SSHD_BIN" -T 2>/dev/null)" || return 1
    fi

    LSSHM_SSHD_T_CACHE="$dump"
    LSSHM_SSHD_T_CACHED=1
    mkdir -p "$(dirname "$cache_file")" 2>/dev/null || true
    printf '%s\n' "$dump" >"$cache_file" 2>/dev/null || true
    printf '%s\n' "$dump"
}

# Effective value of a directive (lowercase key). Falls back to file parsing
# when sshd -T is unavailable (e.g. no sudo credentials yet).
lsshm_server_config_effective_value() {
    local key; key="$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')"
    local dump val
    dump="$(lsshm_server_config_dump)" || dump=""
    if [ -n "$dump" ]; then
        val="$(printf '%s\n' "$dump" | awk -v k="$key" 'tolower($1)==k {sub($1 FS,""); print; exit}')"
        [ -n "$val" ] && { printf '%s' "$val"; return 0; }
    fi
    # Fallback: first matching non-comment line across config + includes.
    lsshm_config_parse_value "$key"
}

# Parse a directive value directly from files (first occurrence wins, like sshd).
lsshm_config_parse_value() {
    local key; key="$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')"
    local files; files="$(lsshm_config_effective_files)"
    local f val=""
    while IFS= read -r f; do
        [ -r "$f" ] || continue
        val="$(awk -v k="$key" '
            { line=$0; sub(/#.*/,"",line);
              n=split(line,a," ");
              if (n>=2 && tolower(a[1])==k) { $1=""; sub(/^ /,""); print; exit } }' "$f")"
        [ -n "$val" ] && { printf '%s' "$val"; return 0; }
    done <<EOF
$files
EOF
    printf ''
}

# Ordered list of configuration files: main file, then Include targets in
# lexical order (a simplified model of OpenSSH include handling).
lsshm_config_effective_files() {
    [ -r "$LSSHM_SSHD_CONFIG" ] || { printf '%s\n' "$LSSHM_SSHD_CONFIG"; return; }
    local line trimmed keyword rest pattern g
    # Emit files in the order they are referenced in the main file, expanding
    # Include directives at the point where they appear. Uses bash string
    # operations only (no per-line subprocess) so it stays fast on any host.
    while IFS= read -r line; do
        trimmed="${line#"${line%%[![:space:]]*}"}"
        keyword="${trimmed%%[[:space:]]*}"
        case "$keyword" in
            [Ii]nclude)
                rest="${trimmed#"$keyword"}"
                rest="${rest#"${rest%%[![:space:]]*}"}"
                for pattern in $rest; do
                    case "$pattern" in
                        /*) : ;;
                        *) pattern="/etc/ssh/$pattern" ;;
                    esac
                    for g in $pattern; do
                        [ -f "$g" ] && printf '%s\n' "$g"
                    done
                done
                ;;
        esac
    done <"$LSSHM_SSHD_CONFIG"
    # The main file itself participates too (directives outside includes).
    printf '%s\n' "$LSSHM_SSHD_CONFIG"
}

# Detect whether the main config defines a directive BEFORE its Include line.
# Such an early definition would win over the managed drop-in.
lsshm_config_defined_before_include() {
    local key; key="$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')"
    [ -r "$LSSHM_SSHD_CONFIG" ] || return 1
    awk -v k="$key" '
        BEGIN{seen=0; inc=0}
        {
            line=$0; sub(/#.*/,"",line);
            n=split(line,a," ");
            if (n>=1 && tolower(a[1])=="include") { inc=1 }
            if (!inc && n>=2 && tolower(a[1])==k) { seen=1 }
        }
        END{ exit (seen?0:1) }
    ' "$LSSHM_SSHD_CONFIG"
}

# --- managed drop-in ---------------------------------------------------------

lsshm_managed_ensure_include() {
    # Warn if the main config has no Include for sshd_config.d.
    [ -r "$LSSHM_SSHD_CONFIG" ] || return 0
    if ! grep -Eqi '^[[:space:]]*Include[[:space:]]+.*sshd_config\.d' "$LSSHM_SSHD_CONFIG"; then
        lsshm_warn 'The main config file does not include sshd_config.d/.'
        lsshm_warn 'The file managed by LSSHM might be ignored.'
    fi
}

# Read current value from the managed file only.
lsshm_managed_get() {
    local key; key="$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')"
    local awk_prog='{ n=split($0,a," "); if (n>=2 && tolower(a[1])==k){ $1=""; sub(/^ /,""); print; exit } }'
    if [ -r "$LSSHM_MANAGED_CONF" ]; then
        awk -v k="$key" "$awk_prog" "$LSSHM_MANAGED_CONF" 2>/dev/null
        return 0
    fi
    [ -e "$LSSHM_MANAGED_CONF" ] || return 1
    lsshm_run_privileged awk -v k="$key" "$awk_prog" "$LSSHM_MANAGED_CONF" 2>/dev/null
}

# Upsert a directive into the managed drop-in file and validate.
# Usage: lsshm_managed_set KEY VALUE
lsshm_managed_set() {
    local key="$1" value="$2"
    lsshm_require_root
    lsshm_managed_ensure_include

    if lsshm_config_defined_before_include "$key"; then
        lsshm_warn "'%s' is defined in %s before the Include." "$key" "$LSSHM_SSHD_CONFIG"
        lsshm_warn 'This value will take precedence over the file managed by LSSHM.'
        if lsshm_confirm "$(lsshm_t 'Comment out this definition in the main file?')" no; then
            lsshm_config_comment_directive "$key"
        fi
    fi

    local tmp; tmp="$(lsshm_mktemp)"
    # Start from existing managed file or a fresh header (one sudo for the read).
    if [ -r "$LSSHM_MANAGED_CONF" ]; then
        cat "$LSSHM_MANAGED_CONF" >"$tmp" 2>/dev/null || true
    elif [ -e "$LSSHM_MANAGED_CONF" ]; then
        lsshm_run_privileged cat "$LSSHM_MANAGED_CONF" >"$tmp" 2>/dev/null || true
    fi
    if [ ! -s "$tmp" ]; then
        printf '%s\n\n' "$LSSHM_MANAGED_HEADER" >"$tmp"
    fi

    # Remove any existing line for this key, then append the new value.
    local tmp2; tmp2="$(lsshm_mktemp)"
    awk -v k="$key" '
        { n=split($0,a," "); if (n>=1 && tolower(a[1])==tolower(k)) next; print }
    ' "$tmp" >"$tmp2"
    printf '%s %s\n' "$key" "$value" >>"$tmp2"

    # Install atomically with correct permissions, then validate.
    lsshm_backup_file "$LSSHM_MANAGED_CONF" "managed-conf" >/dev/null 2>&1 || true
    lsshm_run_privileged install -m 0644 -o root -g root "$tmp2" "$LSSHM_MANAGED_CONF"
    lsshm_server_config_invalidate_cache

    if ! lsshm_server_config_test; then
        lsshm_error 'New configuration invalid: rolling back.'
        lsshm_run_privileged install -m 0644 "$tmp" "$LSSHM_MANAGED_CONF" 2>/dev/null || true
        lsshm_server_config_invalidate_cache
        return 1
    fi
    lsshm_ok 'Directive applied: %s %s' "$key" "$value"

    # Confirm the effective runtime value matches the intended choice.
    local eff_key eff_val norm_eff norm_want
    eff_key="$(printf '%s' "$key" | tr '[:upper:]' '[:lower:]')"
    # Prefer a fresh privileged dump when credentials are already warm.
    lsshm_server_config_dump >/dev/null 2>&1 || true
    eff_val="$(lsshm_server_config_effective_value "$eff_key")"
    if [ -n "$eff_val" ]; then
        norm_eff="$(printf '%s' "$eff_val" | tr '[:upper:]' '[:lower:]')"
        norm_want="$(printf '%s' "$value" | tr '[:upper:]' '[:lower:]')"
        case "$eff_key" in
            permitrootlogin)
                [ "$norm_eff" = "without-password" ] && norm_eff="prohibit-password"
                ;;
        esac
        if [ "$norm_eff" != "$norm_want" ]; then
            lsshm_warn 'Effective value (sshd -T): %s' "$eff_val"
            lsshm_warn 'Expected: %s - another definition may still take precedence.' "$value"
        fi
    fi
    return 0
}

# Comment out a directive in the main config (with backup).
lsshm_config_comment_directive() {
    local key="$1"
    lsshm_backup_file "$LSSHM_SSHD_CONFIG" "main-config" >/dev/null 2>&1 || true
    local tmp; tmp="$(lsshm_mktemp)"
    lsshm_run_privileged awk -v k="$key" '
        { n=split($0,a," ");
          if (n>=2 && tolower(a[1])==tolower(k) && a[1] !~ /^#/)
              print "# LSSHM disabled: " $0;
          else print }
    ' "$LSSHM_SSHD_CONFIG" >"$tmp"
    lsshm_run_privileged install -m 0644 "$tmp" "$LSSHM_SSHD_CONFIG"
}

# --- human-readable directives ----------------------------------------------

lsshm_rootlogin_label() {
    case "$1" in
        no)                   lsshm_t 'forbidden' ;;
        prohibit-password|without-password) lsshm_t 'key only' ;;
        yes)                  lsshm_t 'key or password' ;;
        forced-commands-only) lsshm_t 'forced commands only' ;;
        "")                   lsshm_t 'not set' ;;
        *)                    printf '%s' "$1" ;;
    esac
}

lsshm_set_root_login() {
    lsshm_header
    lsshm_out 'SSH root login'; printf '\n'
    lsshm_out '  1. Forbid root entirely'
    lsshm_out '  2. Allow root with a key only'
    lsshm_out '  3. Allow root with a key or a password'
    lsshm_out '  4. Allow root only for forced commands'; printf '\n'
    lsshm_out 'Recommendation: allow root with a key only,'
    lsshm_out 'or use a normal user with sudo.'; printf '\n'
    local choice; choice="$(lsshm_prompt "$(lsshm_t 'Choice')" '2')"
    local value=""
    case "$choice" in
        1) value="no" ;;
        2) value="prohibit-password" ;;
        3) value="yes" ;;
        4) value="forced-commands-only" ;;
        *) lsshm_info 'No change.'; return 0 ;;
    esac
    lsshm_apply_dangerous_change "PermitRootLogin" "$value" "$(lsshm_t 'root access change')"
}

lsshm_set_password_auth() {
    local cur; cur="$(lsshm_server_config_effective_value passwordauthentication)"
    lsshm_info 'Current password authentication: %s' "$(lsshm_yesno_label "$cur")"
    if lsshm_confirm "$(lsshm_t 'Allow password authentication?')" no; then
        lsshm_managed_set "PasswordAuthentication" "yes" && lsshm_server_reload
    else
        lsshm_warn 'Disabling passwords may lock you out without a valid key.'
        lsshm_apply_dangerous_change "PasswordAuthentication" "no" "$(lsshm_t 'disabling passwords')"
    fi
}

lsshm_set_pubkey_auth() {
    if lsshm_confirm "$(lsshm_t 'Allow public key authentication?')" yes; then
        lsshm_managed_set "PubkeyAuthentication" "yes" && lsshm_server_reload
    else
        lsshm_warn 'Disabling key authentication may lock you out.'
        lsshm_apply_dangerous_change "PubkeyAuthentication" "no" "$(lsshm_t 'disabling key authentication')"
    fi
}

lsshm_set_port() {
    local cur; cur="$(lsshm_server_config_effective_value port)"; cur="${cur:-22}"
    local port; port="$(lsshm_prompt "$(lsshm_t 'New SSH port')" "$cur")"
    case "$port" in
        ''|*[!0-9]*) lsshm_error 'Invalid port.'; return 1 ;;
    esac
    if [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]; then
        lsshm_error 'Port out of range (1-65535).'; return 1
    fi
    lsshm_warn 'Check your firewall before changing the port.'
    lsshm_apply_dangerous_change "Port" "$port" "$(lsshm_t 'port change')"
}

lsshm_set_allow_users() {
    local cur; cur="$(lsshm_server_config_effective_value allowusers)"
    lsshm_info 'Current AllowUsers: %s' "${cur:-$(lsshm_t 'not set')}"
    local users; users="$(lsshm_prompt "$(lsshm_t 'Allowed users (space-separated, empty = remove)')" "$cur")"
    if [ -z "$users" ]; then
        lsshm_info 'Removing AllowUsers is not handled automatically (edit the managed file).'
        return 0
    fi
    lsshm_apply_dangerous_change "AllowUsers" "$users" "$(lsshm_t 'AllowUsers change')"
}

lsshm_set_allow_groups() {
    local cur; cur="$(lsshm_server_config_effective_value allowgroups)"
    lsshm_info 'Current AllowGroups: %s' "${cur:-$(lsshm_t 'not set')}"
    local groups; groups="$(lsshm_prompt "$(lsshm_t 'Allowed groups (space-separated)')" "$cur")"
    [ -z "$groups" ] && { lsshm_info 'No change.'; return 0; }
    lsshm_apply_dangerous_change "AllowGroups" "$groups" "$(lsshm_t 'AllowGroups change')"
}

# Show the effective configuration (sshd -T) or a helpful message.
lsshm_server_config_show() {
    local dump
    # Explicit request: allow one sudo prompt to get the real effective dump.
    dump="$(lsshm_server_config_dump refresh)" || dump="$(lsshm_server_config_dump)" || dump=""
    if [ -n "$dump" ]; then
        printf '%s\n' "$dump" | sort
    else
        lsshm_warn 'sshd -T unavailable. Detected configuration files:'
        lsshm_config_effective_files
    fi
}

# ===== src/rollback.sh =================================================
# shellcheck shell=bash
# =============================================================================
# rollback.sh - safe application of dangerous changes with automatic rollback
# =============================================================================
# Dangerous changes (port, disabling passwords, root access, AllowUsers,
# PubkeyAuthentication, ListenAddress) can lock a remote administrator out.
# LSSHM therefore:
#   1. backs up the configuration
#   2. schedules an automatic restore
#   3. applies the change and reloads SSH
#   4. verifies the port is listening
#   5. asks for confirmation from a second session (never auto-kept via -y)
#   6. cancels the automatic restore only after confirmation

LSSHM_ROLLBACK_UNIT="lsshm-rollback"
LSSHM_ROLLBACK_DELAY="${LSSHM_ROLLBACK_DELAY:-120}"

# True when a controlling TTY is available (ignores LSSHM_ASSUME_YES).
lsshm_can_prompt_tty() {
    [ -t 0 ] && [ -t 1 ] && return 0
    lsshm_have_tty && return 0
    return 1
}

# Prompt that always reads the TTY; never auto-answered by -y.
# Used for the post-change rollback confirmation.
lsshm_prompt_tty() {
    local prompt="$1" default="${2:-}" answer="" msg=""
    if [ -n "$default" ]; then
        msg="${prompt} [${default}]: "
    else
        msg="${prompt}: "
    fi
    if ! lsshm_read_line answer "$msg"; then
        printf '%s' "$default"
        return 0
    fi
    printf '%s' "${answer:-$default}"
}

# Build a self-contained restore script that reverts to a backup archive.
lsshm_rollback_build_script() {
    local archive="$1" confirm_flag="$2" delay="$3"
    # persist: must not be deleted by the EXIT cleanup trap.
    local script; script="$(lsshm_mktemp persist)"
    cat >"$script" <<EOF
#!/bin/sh
# LSSHM automatic rollback helper
sleep "$delay"
if [ -f "$confirm_flag" ]; then
    rm -f "$confirm_flag"
    exit 0
fi
tar -xzf "$archive" -C / 2>/dev/null
if command -v systemctl >/dev/null 2>&1; then
    systemctl reload "$LSSHM_SSH_SERVICE" 2>/dev/null || systemctl restart "$LSSHM_SSH_SERVICE" 2>/dev/null
elif command -v rc-service >/dev/null 2>&1; then
    rc-service "$LSSHM_SSH_SERVICE" restart 2>/dev/null
else
    service "$LSSHM_SSH_SERVICE" restart 2>/dev/null
fi
EOF
    chmod +x "$script"
    printf '%s' "$script"
}

lsshm_rollback_schedule() {
    # lsshm_rollback_schedule SCRIPT DELAY -> echoes cancel token
    local script="$1" delay="$2"
    if [ "$LSSHM_HAS_SYSTEMD" = "1" ] && lsshm_have systemd-run; then
        lsshm_run_privileged systemd-run --unit="$LSSHM_ROLLBACK_UNIT" \
            --description="LSSHM automatic SSH rollback" \
            /bin/sh "$script" >/dev/null 2>&1 && { printf 'systemd'; return 0; }
    fi
    # Fallback: detached nohup process. Cancellation relies on the confirm flag.
    lsshm_run_privileged sh -c "nohup /bin/sh '$script' >/dev/null 2>&1 &"
    printf 'nohup'
}

lsshm_rollback_cancel() {
    local method="$1" confirm_flag="$2"
    # The confirm flag stops both methods when the helper wakes up.
    lsshm_run_privileged touch "$confirm_flag" 2>/dev/null || true
    if [ "$method" = "systemd" ] && lsshm_have systemctl; then
        lsshm_run_privileged systemctl stop "$LSSHM_ROLLBACK_UNIT" 2>/dev/null || true
        lsshm_run_privileged systemctl reset-failed "$LSSHM_ROLLBACK_UNIT" 2>/dev/null || true
    fi
}

# Main entry used by server_config.sh for dangerous directives.
lsshm_apply_dangerous_change() {
    local key="$1" value="$2" description="$3"

    # Dangerous changes require a TTY so the operator can confirm from a second session.
    # -y may auto-confirm the initial consent, but never skips the rollback safety net.
    if ! lsshm_can_prompt_tty; then
        lsshm_error 'Sensitive change not possible without an interactive terminal: %s' "$description"
        lsshm_info 'A TTY is required to confirm the new SSH session works.'
        return 1
    fi

    lsshm_warn 'Sensitive change: %s' "$description"
    if ! lsshm_confirm "$(lsshm_t 'Continue with an automatic safety rollback?')" no; then
        lsshm_info 'Cancelled.'
        return 1
    fi

    # 1. Backup.
    local archive; archive="$(lsshm_backup_server_config)" || return 1

    # 2. Apply the change (validates internally).
    if ! lsshm_managed_set "$key" "$value"; then
        lsshm_error 'Change application cancelled.'
        return 1
    fi

    # 3. Always schedule automatic restore (never skip under -y).
    local confirm_flag="$LSSHM_STATE_DIR/rollback.confirm"
    lsshm_run_privileged rm -f "$confirm_flag" 2>/dev/null || true
    local script; script="$(lsshm_rollback_build_script "$archive" "$confirm_flag" "$LSSHM_ROLLBACK_DELAY")"
    local method; method="$(lsshm_rollback_schedule "$script" "$LSSHM_ROLLBACK_DELAY")"

    # 4. Reload SSH.
    lsshm_server_reload || true

    # 5. Verify the port listens.
    if lsshm_server_port_listening; then
        lsshm_ok 'The SSH port is listening.'
    else
        lsshm_warn 'Unable to confirm the SSH port is listening.'
    fi

    # 6. Ask for confirmation from a second session (never auto-kept via -y).
    printf '\n'
    lsshm_out 'The new configuration is active.'; printf '\n'
    lsshm_out 'An automatic rollback will occur in %s seconds.' "$LSSHM_ROLLBACK_DELAY"; printf '\n'
    lsshm_out 'Open a second SSH connection before confirming.'; printf '\n'
    lsshm_out '  1. The new connection works'
    lsshm_out '  2. Restore immediately'
    local choice; choice="$(lsshm_prompt_tty "$(lsshm_t 'Choice')" '2')"
    case "$choice" in
        1)
            lsshm_rollback_cancel "$method" "$confirm_flag"
            lsshm_ok 'Automatic rollback cancelled. Change kept.'
            ;;
        *)
            lsshm_warn 'Restoring immediately...'
            lsshm_run_privileged tar -xzf "$archive" -C / 2>/dev/null || true
            lsshm_rollback_cancel "$method" "$confirm_flag"
            lsshm_server_reload || true
            lsshm_ok 'Previous configuration restored.'
            ;;
    esac
}

# ===== src/users.sh ====================================================
# shellcheck shell=bash
# =============================================================================
# users.sh - local user helpers
# =============================================================================

# List human/login users (UID >= 1000) plus root.
lsshm_users_list() {
    if lsshm_have getent; then
        getent passwd | awk -F: '($3==0)||($3>=1000 && $3<65534){print $1":"$3":"$6}'
    else
        awk -F: '($3==0)||($3>=1000 && $3<65534){print $1":"$3":"$6}' /etc/passwd
    fi
}

lsshm_users_print() {
    lsshm_info 'Local users:'
    local name uid home
    while IFS=: read -r name uid home; do
        printf '  %-16s uid=%-6s %s\n' "$name" "$uid" "$home"
    done <<EOF
$(lsshm_users_list)
EOF
}

lsshm_user_exists() {
    if lsshm_have getent; then
        getent passwd "$1" >/dev/null 2>&1
    else
        grep -q "^$1:" /etc/passwd 2>/dev/null
    fi
}

# Count authorized keys for a user. Quiet: returns 0 when unreadable without
# attempting privilege elevation (used in the status panel).
lsshm_user_key_count() {
    local user="$1" home ak count
    home="$(lsshm_user_home "$user")"
    ak="$home/.ssh/authorized_keys"
    if [ -r "$ak" ]; then
        count="$(grep -Ecv '^[[:space:]]*($|#)' "$ak" 2>/dev/null)"
        printf '%s' "${count:-0}"
    else
        printf '0'
    fi
}

# ===== src/authorized_keys.sh ==========================================
# shellcheck shell=bash
# =============================================================================
# authorized_keys.sh - incoming access: keys allowed to reach THIS machine
# =============================================================================
# This manages ~/.ssh/authorized_keys for a given user. These are the public
# keys that are ALLOWED TO CONNECT to this machine.

lsshm_access_file() {
    local user="${1:-$LSSHM_CALLING_USER}"
    printf '%s/.ssh/authorized_keys' "$(lsshm_user_home "$user")"
}

# Read the authorized_keys file (with privileges if needed).
lsshm_access_read() {
    local file="$1"
    if [ -r "$file" ]; then
        cat "$file"
    elif lsshm_can_elevate; then
        lsshm_run_privileged cat "$file" 2>/dev/null
    fi
}

# Compute the SHA256 fingerprint and type of a single key line.
lsshm_access_fingerprint_line() {
    local line="$1" tmp out
    tmp="$(lsshm_mktemp)"
    printf '%s\n' "$line" >"$tmp"
    out="$(ssh-keygen -lf "$tmp" 2>/dev/null)" || { printf ''; return 1; }
    printf '%s' "$out"
}

# Classify a line from authorized_keys for shared indexing.
# Sets: _ak_kind (active|disabled|skip), _ak_keyline (raw key line to fingerprint).
lsshm_access_classify_line() {
    local line="$1"
    _ak_kind="skip"
    _ak_keyline=""
    case "$line" in
        '# LSSHM-DISABLED '*)
            _ak_kind="disabled"
            _ak_keyline="${line#\# LSSHM-DISABLED }"
            ;;
        ''|'#'*)
            _ak_kind="skip"
            ;;
        *)
            _ak_kind="active"
            _ak_keyline="$line"
            ;;
    esac
}

# List authorized keys for a user with details.
# Indexing includes both active and LSSHM-DISABLED entries (same as remove/disable).
lsshm_access_list() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local file; file="$(lsshm_access_file "$user")"
    lsshm_out 'User : %s' "$user"
    lsshm_out 'File : %s' "$file"
    printf '\n'

    local content; content="$(lsshm_access_read "$file")"
    if [ -z "$content" ]; then
        lsshm_info 'No authorized key.'
        return 0
    fi

    local i=0 line fp bits type comment info
    while IFS= read -r line; do
        lsshm_access_classify_line "$line"
        [ "$_ak_kind" = "skip" ] && continue
        i=$((i+1))
        info="$(lsshm_access_fingerprint_line "$_ak_keyline")"
        bits="$(printf '%s' "$info" | awk '{print $1}')"
        fp="$(printf '%s' "$info" | awk '{print $2}')"
        type="$(printf '%s' "$info" | awk '{print $NF}' | tr -d '()')"
        # Comment = fields after key type + key body (options may precede the type).
        comment="$(printf '%s' "$_ak_keyline" | awk '
            {
              for (i=1;i<=NF;i++) {
                if ($i ~ /^(ssh-ed25519|ssh-rsa|ssh-dss|ecdsa-sha2-nistp[0-9]+|sk-ssh-ed25519@openssh\.com|sk-ecdsa-sha2-nistp256@openssh\.com)$/) {
                  if (i+2<=NF) { for (j=i+2;j<=NF;j++) printf "%s%s", $j, (j<NF?" ":""); }
                  exit
                }
              }
            }')"
        local nocomment; nocomment="$(lsshm_t 'no comment')"
        if [ "$_ak_kind" = "disabled" ]; then
            printf '%d. [%s] %s\n' "$i" "$(lsshm_t 'DISABLED')" "${comment:-$nocomment}"
        else
            printf '%d. %s\n' "$i" "${comment:-$nocomment}"
        fi
        lsshm_out '   Type        : %s (%s bits)' "${type:-?}" "${bits:-?}"
        lsshm_out '   Fingerprint : %s' "${fp:-$(lsshm_t 'unknown')}"
        case "$_ak_keyline" in
            *from=*)       lsshm_out '   Restriction : %s' "$(printf '%s' "$_ak_keyline" | grep -o 'from="[^"]*"')" ;;
        esac
        case "$_ak_keyline" in
            *command=*)    lsshm_out '   Command     : %s' "$(printf '%s' "$_ak_keyline" | grep -o 'command="[^"]*"')" ;;
        esac
        case "$_ak_keyline" in
            *no-port-forwarding*) lsshm_out '   Forwarding  : forbidden' ;;
        esac
    done <<EOF
$content
EOF
}

# Write new content to the authorized_keys file with correct ownership/perms.
lsshm_access_write() {
    local user="$1" file="$2" tmp="$3"
    local home; home="$(lsshm_user_home "$user")"
    local ssh_dir="$home/.ssh"
    local uid gid
    uid="$(id -u "$user" 2>/dev/null || echo 0)"
    gid="$(id -g "$user" 2>/dev/null || echo 0)"

    # As root, always set ownership: writable dirs would otherwise leave
    # root:root files that StrictModes rejects for the target user.
    if [ "${LSSHM_IS_ROOT:-0}" = "1" ]; then
        mkdir -p "$ssh_dir"
        install -m 0600 -o "$uid" -g "$gid" "$tmp" "$file"
        chmod 700 "$ssh_dir"
        chown "$uid:$gid" "$ssh_dir"
    elif [ -w "$ssh_dir" ] || { [ ! -e "$ssh_dir" ] && [ -w "$home" ]; }; then
        mkdir -p "$ssh_dir"
        install -m 0600 "$tmp" "$file"
        chmod 700 "$ssh_dir"
    else
        lsshm_run_privileged mkdir -p "$ssh_dir"
        lsshm_run_privileged install -m 0600 -o "$uid" -g "$gid" "$tmp" "$file"
        lsshm_run_privileged chmod 700 "$ssh_dir"
        lsshm_run_privileged chown "$uid:$gid" "$ssh_dir"
    fi
}

# Add a public key (pasted or from a .pub file).
lsshm_access_add() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local keyline="${2:-}"
    if [ -z "$keyline" ]; then
        if lsshm_is_interactive; then
            lsshm_out 'Paste the public key (one line), then Enter:'
            read -r keyline </dev/tty || keyline=""
        fi
    fi
    # Support importing from a file path.
    if [ -f "$keyline" ]; then
        keyline="$(cat "$keyline")"
    fi
    [ -n "$keyline" ] || { lsshm_error 'No key provided.'; return 1; }

    # Validate that it parses as a key.
    if ! lsshm_access_fingerprint_line "$keyline" >/dev/null; then
        lsshm_error 'The provided key is not a valid public key.'
        return 1
    fi

    local file; file="$(lsshm_access_file "$user")"
    lsshm_backup_authorized_keys "$user" >/dev/null 2>&1 || true
    local tmp; tmp="$(lsshm_mktemp)"
    lsshm_access_read "$file" >"$tmp" 2>/dev/null || true

    # Duplicate detection by fingerprint (active and LSSHM-DISABLED entries).
    local newfp; newfp="$(lsshm_access_fingerprint_line "$keyline" | awk '{print $2}')"
    local existing efp
    while IFS= read -r existing || [ -n "$existing" ]; do
        lsshm_access_classify_line "$existing"
        [ "$_ak_kind" = "skip" ] && continue
        efp="$(lsshm_access_fingerprint_line "$_ak_keyline" | awk '{print $2}')"
        if [ -n "$efp" ] && [ "$efp" = "$newfp" ]; then
            if [ "$_ak_kind" = "disabled" ]; then
                lsshm_warn 'This key already exists (disabled, fingerprint %s).' "$efp"
                lsshm_info 'Re-enable it via the Disable / re-enable a key entry.'
            else
                lsshm_warn 'This key is already authorized (fingerprint %s).' "$efp"
            fi
            return 0
        fi
    done <"$tmp"

    printf '%s\n' "$keyline" >>"$tmp"
    lsshm_access_write "$user" "$file" "$tmp"
    lsshm_ok 'Key added for %s.' "$user"
}

# Remove a key by fingerprint or by 1-based index (same numbering as list).
lsshm_access_remove() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local target="${2:-}"
    local file; file="$(lsshm_access_file "$user")"
    local content; content="$(lsshm_access_read "$file")"
    [ -n "$content" ] || { lsshm_info 'No key to remove.'; return 0; }

    if [ -z "$target" ]; then
        lsshm_access_list "$user"
        target="$(lsshm_prompt "$(lsshm_t 'SHA256 fingerprint or number to remove')" '')"
    fi
    [ -n "$target" ] || { lsshm_info 'Cancelled.'; return 0; }

    lsshm_backup_authorized_keys "$user" >/dev/null 2>&1 || true
    local tmp; tmp="$(lsshm_mktemp)"
    local i=0 removed=0 line fp
    while IFS= read -r line; do
        lsshm_access_classify_line "$line"
        if [ "$_ak_kind" = "skip" ]; then
            printf '%s\n' "$line" >>"$tmp"
            continue
        fi
        i=$((i+1))
        fp="$(lsshm_access_fingerprint_line "$_ak_keyline" | awk '{print $2}')"
        if [ "$target" = "$i" ] || { [ -n "$fp" ] && [ "$target" = "$fp" ]; }; then
            removed=1
            continue
        fi
        printf '%s\n' "$line" >>"$tmp"
    done <<EOF
$content
EOF
    if [ "$removed" = "0" ]; then
        lsshm_warn 'No matching key found.'
        return 1
    fi
    lsshm_access_write "$user" "$file" "$tmp"
    lsshm_ok 'Key removed for %s.' "$user"
}

# Repair ownership and permissions of the user's .ssh directory.
lsshm_access_repair() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local home; home="$(lsshm_user_home "$user")"
    local ssh_dir="$home/.ssh"
    local uid gid
    uid="$(id -u "$user" 2>/dev/null || echo 0)"
    gid="$(id -g "$user" 2>/dev/null || echo 0)"

    [ -d "$ssh_dir" ] || { lsshm_warn '%s does not exist.' "$ssh_dir"; return 0; }

    local runner=""
    [ -w "$ssh_dir" ] || runner="lsshm_run_privileged"

    $runner chown -R "$uid:$gid" "$ssh_dir"
    $runner chmod 700 "$ssh_dir"
    [ -e "$ssh_dir/authorized_keys" ] && $runner chmod 600 "$ssh_dir/authorized_keys"
    local f
    for f in "$ssh_dir"/id_* "$ssh_dir"/*.pub; do
        [ -e "$f" ] || continue
        case "$f" in
            *.pub) $runner chmod 644 "$f" ;;
            *)     $runner chmod 600 "$f" ;;
        esac
    done
    lsshm_ok 'Permissions repaired for %s:' "$user"
    lsshm_info '  .ssh 700, authorized_keys 600, private keys 600, public keys 644'
}

# Temporarily disable or re-enable a key by fingerprint or index (same numbering as list).
lsshm_access_disable() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local target="${2:-}"
    local file; file="$(lsshm_access_file "$user")"
    local content; content="$(lsshm_access_read "$file")"
    [ -n "$content" ] || { lsshm_info 'No key to disable.'; return 0; }

    if [ -z "$target" ]; then
        lsshm_access_list "$user"
        target="$(lsshm_prompt "$(lsshm_t 'SHA256 fingerprint or number to disable/re-enable')" '')"
    fi
    [ -n "$target" ] || { lsshm_info 'Cancelled.'; return 0; }

    lsshm_backup_authorized_keys "$user" >/dev/null 2>&1 || true
    local tmp; tmp="$(lsshm_mktemp)"
    local i=0 changed=0 line fp
    while IFS= read -r line; do
        lsshm_access_classify_line "$line"
        if [ "$_ak_kind" = "skip" ]; then
            printf '%s\n' "$line" >>"$tmp"
            continue
        fi
        i=$((i+1))
        fp="$(lsshm_access_fingerprint_line "$_ak_keyline" | awk '{print $2}')"
        if [ "$target" = "$i" ] || { [ -n "$fp" ] && [ "$target" = "$fp" ]; }; then
            if [ "$_ak_kind" = "disabled" ]; then
                printf '%s\n' "$_ak_keyline" >>"$tmp"
            else
                printf '# LSSHM-DISABLED %s\n' "$line" >>"$tmp"
            fi
            changed=1
        else
            printf '%s\n' "$line" >>"$tmp"
        fi
    done <<EOF
$content
EOF
    if [ "$changed" = "0" ]; then
        lsshm_warn 'No matching key found.'
        return 1
    fi
    lsshm_access_write "$user" "$file" "$tmp"
    lsshm_ok 'Key state updated for %s.' "$user"
}

# Detect duplicate keys across the file.
lsshm_access_duplicates() {
    local user="${1:-$LSSHM_CALLING_USER}"
    local file; file="$(lsshm_access_file "$user")"
    local content; content="$(lsshm_access_read "$file")"
    [ -n "$content" ] || { lsshm_info 'No key.'; return 0; }
    local line fp
    printf '%s\n' "$content" | while IFS= read -r line; do
        case "$line" in ''|'#'*) continue ;; esac
        lsshm_access_fingerprint_line "$line" | awk '{print $2}'
    done | sort | uniq -d | while IFS= read -r fp; do
        [ -n "$fp" ] && lsshm_warn 'Duplicate detected: %s' "$fp"
    done
    lsshm_ok 'Duplicate analysis complete.'
}

# ===== src/local_keys.sh ===============================================
# shellcheck shell=bash
# =============================================================================
# local_keys.sh - keys used by THIS machine to connect ELSEWHERE
# =============================================================================
# These are private/public key pairs in ~/.ssh/id_* used for outgoing SSH
# connections. LSSHM must never transmit or display a private key without an
# explicit warning.

lsshm_keys_dir() {
    lsshm_target_ssh_dir
}

# Fill LSSHM_KEY_PATHS with private-key paths (one per .pub found).
# Must be called in the current shell (not via $(...)): arrays do not survive
# command substitution. Sets LSSHM_KEY_COUNT and returns 0.
lsshm_keys_collect() {
    LSSHM_KEY_PATHS=()
    LSSHM_KEY_COUNT=0
    local dir; dir="$(lsshm_keys_dir)"
    [ -d "$dir" ] || return 0
    local pub priv
    # nullglob-safe: skip the literal "*.pub" when the directory is empty.
    for pub in "$dir"/*.pub; do
        [ -e "$pub" ] || continue
        priv="${pub%.pub}"
        LSSHM_KEY_PATHS+=("$priv")
    done
    LSSHM_KEY_COUNT="${#LSSHM_KEY_PATHS[@]}"
}

# Print a numbered list of key pairs (same numbering as pick).
lsshm_keys_print_numbered() {
    local dir; dir="$(lsshm_keys_dir)"
    lsshm_out 'Directory: %s' "$dir"
    printf '\n'
    lsshm_keys_collect
    if [ "${LSSHM_KEY_COUNT:-0}" = "0" ]; then
        lsshm_info 'No key pair detected.'
        return 1
    fi
    local i=0 priv pub info privlabel
    for priv in "${LSSHM_KEY_PATHS[@]}"; do
        i=$((i+1))
        pub="$priv.pub"
        info="$(ssh-keygen -lf "$pub" 2>/dev/null)"
        if [ -f "$priv" ]; then
            privlabel="$priv ($(lsshm_t 'present'))"
        else
            privlabel="$(lsshm_t 'absent')"
        fi
        printf '%d. %s\n' "$i" "$(basename "$priv")"
        lsshm_out '   Public key  : %s' "$pub"
        lsshm_out '   Private key : %s' "$privlabel"
        lsshm_out '   Fingerprint : %s' "${info:-$(lsshm_t 'unknown')}"
    done
    return 0
}

# Detect existing key pairs (files with a matching .pub).
lsshm_keys_list() {
    lsshm_keys_print_numbered || true
}

# Interactive picker: list keys, ask for a number (or accept an existing path).
# Usage: path="$(lsshm_keys_pick 'Prompt' [require_private=0|1])"
# Echoes the private-key path (without .pub), or empty on cancel.
lsshm_keys_pick() {
    local prompt="${1:-Choose a key}"
    local require_priv="${2:-0}"
    local given="${3:-}"

    # Non-interactive / explicit path argument.
    if [ -n "$given" ]; then
        local path="$given"
        case "$path" in *.pub) path="${path%.pub}" ;; esac
        if [ "$require_priv" = "1" ] && [ ! -f "$path" ]; then
            lsshm_error 'Private key not found: %s' "$path" >&2
            return 1
        fi
        if [ ! -f "$path.pub" ] && [ ! -f "$path" ]; then
            lsshm_error 'Key not found: %s' "$given" >&2
            return 1
        fi
        printf '%s' "$path"
        return 0
    fi

    # List on stderr so only the selected path is captured on stdout.
    if ! lsshm_keys_print_numbered >&2; then
        return 1
    fi
    printf '\n' >&2
    local choice; choice="$(lsshm_prompt "$(lsshm_tf '%s (number)' "$(lsshm_t "$prompt")")" '')"
    if [ -z "$choice" ]; then
        lsshm_info 'Cancelled.' >&2
        return 1
    fi

    # Allow typing a path as fallback.
    if [ -f "$choice" ] || [ -f "$choice.pub" ]; then
        case "$choice" in *.pub) choice="${choice%.pub}" ;; esac
        printf '%s' "$choice"
        return 0
    fi

    case "$choice" in
        ''|*[!0-9]*)
            lsshm_error 'Invalid choice: %s' "$choice" >&2
            return 1
            ;;
    esac
    if [ "$choice" -lt 1 ] || [ "$choice" -gt "${#LSSHM_KEY_PATHS[@]}" ]; then
        lsshm_error 'Number out of range (1-%s).' "${#LSSHM_KEY_PATHS[@]}" >&2
        return 1
    fi

    local path="${LSSHM_KEY_PATHS[$((choice-1))]}"
    if [ "$require_priv" = "1" ] && [ ! -f "$path" ]; then
        lsshm_error 'Private key missing for %s.' "$(basename "$path")" >&2
        return 1
    fi
    printf '%s' "$path"
    return 0
}

# Generate a new key pair. Default type ED25519.
lsshm_keys_generate() {
    local dir; dir="$(lsshm_keys_dir)"
    lsshm_ensure_user_ssh_dir "$LSSHM_CALLING_USER"

    local type; type="$(lsshm_prompt "$(lsshm_t 'Key type (ed25519/rsa)')" 'ed25519')"
    case "$type" in
        ed25519|ED25519) type="ed25519" ;;
        rsa|RSA)         type="rsa" ;;
        *)               lsshm_warn 'Unknown type, using ed25519.'; type="ed25519" ;;
    esac

    local default_name="id_$type"
    local name; name="$(lsshm_prompt "$(lsshm_t 'File name')" "$default_name")"
    local path="$dir/$name"

    if [ -e "$path" ]; then
        lsshm_warn 'The file %s already exists.' "$path"
        lsshm_confirm "$(lsshm_t 'Overwrite?')" no || { lsshm_info 'Cancelled.'; return 1; }
    fi

    local comment; comment="$(lsshm_prompt "$(lsshm_t 'Comment')" "$LSSHM_CALLING_USER@$(hostname 2>/dev/null || echo host)")"

    local args=(-t "$type" -f "$path" -C "$comment")
    [ "$type" = "rsa" ] && args+=(-b 4096)

    lsshm_info "ssh-keygen ${args[*]}"
    lsshm_info 'A passphrase is strongly recommended.'
    if ssh-keygen "${args[@]}"; then
        chmod 600 "$path" 2>/dev/null || true
        chmod 644 "$path.pub" 2>/dev/null || true
        lsshm_chown_user "$LSSHM_CALLING_USER" "$path" "$path.pub"
        lsshm_ok 'Key generated: %s (user %s)' "$path" "$LSSHM_CALLING_USER"
        lsshm_info 'Public key:'
        cat "$path.pub"
    else
        lsshm_error 'Generation failed.'
        return 1
    fi
}

lsshm_keys_inspect() {
    local path
    path="$(lsshm_keys_pick 'Key to inspect' 0 "${1:-}")" || return 1
    local pub="$path.pub"
    [ -f "$pub" ] || pub="$path"
    if [ ! -f "$pub" ]; then
        lsshm_error 'File not found: %s' "$pub"
        return 1
    fi
    lsshm_info 'Fingerprint:'
    ssh-keygen -lf "$pub"
    lsshm_info 'Random art:'
    ssh-keygen -lvf "$pub" 2>/dev/null | tail -n +1 || true
}

lsshm_keys_export() {
    local path
    path="$(lsshm_keys_pick 'Key to export' 0 "${1:-}")" || return 1
    local pub="$path.pub"
    if [ ! -f "$pub" ]; then
        lsshm_error 'Public key not found: %s' "$pub"
        return 1
    fi
    lsshm_info 'Public key (%s):' "$pub"
    cat "$pub"
}

lsshm_keys_passphrase() {
    local path
    path="$(lsshm_keys_pick 'Key whose passphrase to change' 1 "${1:-}")" || return 1
    lsshm_info 'Changing the passphrase of %s' "$path"
    ssh-keygen -p -f "$path"
}

lsshm_keys_delete() {
    local path
    path="$(lsshm_keys_pick 'Key to delete' 0 "${1:-}")" || return 1
    local priv="$path" pub="$path.pub"

    if [ ! -e "$priv" ] && [ ! -e "$pub" ]; then
        lsshm_error 'No key file found for: %s' "$path"
        return 1
    fi
    lsshm_warn 'Deleting the key pair:'
    [ -e "$priv" ] && printf '  %s\n' "$priv"
    [ -e "$pub" ]  && printf '  %s\n' "$pub"
    lsshm_confirm "$(lsshm_t 'A backup will be created. Confirm deletion?')" no || { lsshm_info 'Cancelled.'; return 0; }

    [ -e "$priv" ] && lsshm_backup_file "$priv" "privkey" >/dev/null 2>&1 || true
    [ -e "$pub" ]  && lsshm_backup_file "$pub" "pubkey" >/dev/null 2>&1 || true
    rm -f "$priv" "$pub"
    lsshm_ok 'Key pair deleted (backup kept).'
}

# ===== src/ssh_agent.sh ================================================
# shellcheck shell=bash
# =============================================================================
# ssh_agent.sh - manage keys loaded into ssh-agent
# =============================================================================

lsshm_agent_available() {
    if [ -z "${SSH_AUTH_SOCK:-}" ]; then
        lsshm_warn 'No ssh-agent detected (SSH_AUTH_SOCK not set).'
        lsshm_info 'Start an agent, e.g.: eval $(ssh-agent -s)'
        return 1
    fi
    return 0
}

lsshm_agent_list() {
    lsshm_agent_available || return 1
    local tmp; tmp="$(lsshm_mktemp)"
    if ssh-add -l >"$tmp" 2>&1; then
        lsshm_info 'Keys loaded in ssh-agent:'
        cat "$tmp"
    else
        lsshm_info "$(cat "$tmp")"
    fi
}

lsshm_agent_add() {
    local path="${1:-}"
    lsshm_agent_available || return 1
    path="$(lsshm_keys_pick 'Key to add to ssh-agent' 1 "$path")" || return 1
    ssh-add "$path" && lsshm_ok 'Key added to ssh-agent.'
}

lsshm_agent_remove() {
    local path="${1:-}"
    lsshm_agent_available || return 1
    if [ -z "$path" ]; then
        if lsshm_confirm "$(lsshm_t 'Remove all keys from the agent?')" no; then
            ssh-add -D && lsshm_ok 'All keys removed.'
            return 0
        fi
    fi
    path="$(lsshm_keys_pick 'Key to remove from ssh-agent' 1 "$path")" || return 1
    ssh-add -d "$path" && lsshm_ok 'Key removed from ssh-agent.'
}

# ===== src/hosts.sh ====================================================
# shellcheck shell=bash
# =============================================================================
# hosts.sh - remote machines managed through ~/.ssh/config (OPTIONAL feature)
# =============================================================================
# These are outgoing connection targets. LSSHM remains fully usable with no
# host configured.

lsshm_hosts_file() {
    printf '%s/config' "$(lsshm_target_ssh_dir)"
}

lsshm_hosts_list() {
    local file; file="$(lsshm_hosts_file)"
    if [ ! -f "$file" ]; then
        lsshm_info 'No ~/.ssh/config file.'
        return 0
    fi
    lsshm_info 'Registered remote hosts (%s):' "$file"
    local count=0 name hostname
    while IFS= read -r name; do
        [ -n "$name" ] || continue
        case "$name" in *'*'*|*'?'*) continue ;; esac
        count=$((count+1))
        hostname="$(lsshm_hosts_get_field "$name" HostName)"
        printf '  %-20s %s\n' "$name" "${hostname:-}"
    done <<EOF
$(awk 'tolower($1)=="host"{for(i=2;i<=NF;i++)print $i}' "$file")
EOF
    [ "$count" = "0" ] && lsshm_info '  (none)'
}

lsshm_hosts_count() {
    local file; file="$(lsshm_hosts_file)"
    [ -f "$file" ] || { printf '0'; return; }
    awk 'tolower($1)=="host"{for(i=2;i<=NF;i++){if($i!~/[*?]/)c++}}END{print c+0}' "$file"
}

# Get a field value from a Host block in the config file.
lsshm_hosts_get_field() {
    local name="$1" field="$2" file
    file="$(lsshm_hosts_file)"
    [ -f "$file" ] || return 1
    awk -v want="$name" -v f="$(printf '%s' "$field" | tr '[:upper:]' '[:lower:]')" '
        tolower($1)=="host" { inblk=0; for(i=2;i<=NF;i++) if($i==want) inblk=1; next }
        inblk && tolower($1)==f { $1=""; sub(/^ /,""); print; exit }
    ' "$file"
}

lsshm_hosts_exists() {
    local name="$1" file
    file="$(lsshm_hosts_file)"
    [ -f "$file" ] || return 1
    awk -v want="$name" 'tolower($1)=="host"{for(i=2;i<=NF;i++) if($i==want){found=1}} END{exit(found?0:1)}' "$file"
}

lsshm_hosts_add() {
    local file; file="$(lsshm_hosts_file)"
    lsshm_ensure_user_ssh_dir "$LSSHM_CALLING_USER"

    local name hostname user port identity proxyjump
    name="$(lsshm_prompt "$(lsshm_t 'Host alias name')" 'proxmox1')"
    [ -n "$name" ] || { lsshm_error 'Name required.'; return 1; }
    if lsshm_hosts_exists "$name"; then
        lsshm_error "A host named '%s' already exists." "$name"
        return 1
    fi
    hostname="$(lsshm_prompt "$(lsshm_t 'Address (HostName)')" '192.168.100.240')"
    user="$(lsshm_prompt "$(lsshm_t 'User')" 'root')"
    port="$(lsshm_prompt "$(lsshm_t 'Port')" '22')"
    identity="$(lsshm_prompt "$(lsshm_t 'Key file (IdentityFile)')" "$(lsshm_keys_dir)/id_ed25519")"
    proxyjump="$(lsshm_prompt "$(lsshm_t 'ProxyJump (empty = none)')" '')"

    {
        printf '\nHost %s\n' "$name"
        printf '    HostName %s\n' "$hostname"
        printf '    User %s\n' "$user"
        printf '    Port %s\n' "$port"
        printf '    IdentityFile %s\n' "$identity"
        printf '    IdentitiesOnly yes\n'
        [ -n "$proxyjump" ] && printf '    ProxyJump %s\n' "$proxyjump"
    } >>"$file"
    chmod 600 "$file" 2>/dev/null || true
    lsshm_chown_user "$LSSHM_CALLING_USER" "$file"
    lsshm_ok "Host '%s' added to %s" "$name" "$file"
}

lsshm_hosts_delete() {
    local name="$1"
    [ -n "$name" ] || name="$(lsshm_prompt "$(lsshm_t 'Host name to delete')" '')"
    [ -n "$name" ] || { lsshm_info 'Cancelled.'; return 0; }
    local file; file="$(lsshm_hosts_file)"
    [ -f "$file" ] || { lsshm_error 'No config file.'; return 1; }
    lsshm_hosts_exists "$name" || { lsshm_error 'Host not found: %s' "$name"; return 1; }

    lsshm_backup_file "$file" "ssh-config" >/dev/null 2>&1 || true
    local tmp; tmp="$(lsshm_mktemp)"
    awk -v want="$name" '
        tolower($1)=="host" {
            skip=0; for(i=2;i<=NF;i++) if($i==want) skip=1;
            if(skip){inblk=1; next} else {inblk=0}
        }
        !inblk { print }
    ' "$file" >"$tmp"
    install -m 0600 "$tmp" "$file"
    lsshm_chown_user "$LSSHM_CALLING_USER" "$file"
    lsshm_ok "Host '%s' deleted." "$name"
}

lsshm_hosts_edit() {
    local name="$1"
    [ -n "$name" ] || name="$(lsshm_prompt "$(lsshm_t 'Host name to edit')" '')"
    lsshm_hosts_exists "$name" || { lsshm_error 'Host not found: %s' "$name"; return 1; }
    lsshm_info "Current configuration of '%s':" "$name"
    lsshm_hosts_show "$name"
    lsshm_warn 'Editing replaces the whole block.'
    lsshm_confirm "$(lsshm_t 'Continue?')" no || return 0
    local file snap
    file="$(lsshm_hosts_file)"
    snap="$(lsshm_mktemp)"
    cp -a "$file" "$snap" 2>/dev/null || { lsshm_error 'Unable to back up %s.' "$file"; return 1; }
    lsshm_hosts_delete "$name"
    if ! lsshm_hosts_add; then
        install -m 0600 "$snap" "$file"
        lsshm_chown_user "$LSSHM_CALLING_USER" "$file"
        lsshm_warn "Edit cancelled: host '%s' has been restored." "$name"
        return 1
    fi
}

lsshm_hosts_show() {
    local name="$1"
    printf '  HostName    : %s\n' "$(lsshm_hosts_get_field "$name" HostName)"
    printf '  User        : %s\n' "$(lsshm_hosts_get_field "$name" User)"
    printf '  Port        : %s\n' "$(lsshm_hosts_get_field "$name" Port)"
    printf '  IdentityFile: %s\n' "$(lsshm_hosts_get_field "$name" IdentityFile)"
    printf '  ProxyJump   : %s\n' "$(lsshm_hosts_get_field "$name" ProxyJump)"
}

lsshm_hosts_effective() {
    local name="$1"
    [ -n "$name" ] || name="$(lsshm_prompt "$(lsshm_t 'Host name')" '')"
    lsshm_have ssh || { lsshm_error 'ssh not found.'; return 1; }
    lsshm_info 'Effective configuration (ssh -G %s):' "$name"
    ssh -G "$name" 2>/dev/null | grep -Ei '^(hostname|user|port|identityfile|proxyjump) '
}

lsshm_hosts_test() {
    local name="$1"
    [ -n "$name" ] || name="$(lsshm_prompt "$(lsshm_t 'Host name to test')" '')"
    local host port
    host="$(lsshm_hosts_get_field "$name" HostName)"; host="${host:-$name}"
    port="$(lsshm_hosts_get_field "$name" Port)"; port="${port:-22}"

    lsshm_info 'Resolving %s...' "$host"
    if lsshm_have getent && getent hosts "$host" >/dev/null 2>&1; then
        lsshm_ok 'DNS resolution succeeded.'
    else
        lsshm_warn 'DNS resolution uncertain.'
    fi

    lsshm_info 'Testing port %s...' "$port"
    if lsshm_have nc && nc -z -w 3 "$host" "$port" 2>/dev/null; then
        lsshm_ok 'Port %s open.' "$port"
    elif (exec 3<>"/dev/tcp/$host/$port") 2>/dev/null; then
        lsshm_ok 'Port %s open.' "$port"
        exec 3>&- 2>/dev/null || true
    else
        lsshm_warn 'Port %s unreachable.' "$port"
    fi

    lsshm_info 'SSH authentication test (BatchMode)...'
    if ssh -o BatchMode=yes -o ConnectTimeout=5 "$name" true 2>/dev/null; then
        lsshm_ok 'Authentication succeeded.'
    else
        lsshm_warn 'Automatic authentication failed (missing key or password required).'
    fi
}

lsshm_hosts_connect() {
    local name="$1"
    [ -n "$name" ] || name="$(lsshm_prompt "$(lsshm_t 'Host name')" '')"
    [ -n "$name" ] || return 1
    lsshm_info 'Connecting to %s...' "$name"
    ssh "$name"
}

lsshm_hosts_copy_key() {
    local name="$1"
    [ -n "$name" ] || name="$(lsshm_prompt "$(lsshm_t 'Host name')" '')"
    lsshm_have ssh-copy-id || { lsshm_error 'ssh-copy-id not found.'; return 1; }
    local identity; identity="$(lsshm_hosts_get_field "$name" IdentityFile)"
    identity="$(lsshm_expand_user_path "${identity:-$(lsshm_keys_dir)/id_ed25519}")"
    local pub="$identity.pub"
    [ -f "$pub" ] || { lsshm_error 'Public key not found: %s' "$pub"; return 1; }
    lsshm_info 'Copying %s to %s...' "$pub" "$name"
    ssh-copy-id -i "$pub" "$name"
}

lsshm_hosts_revoke_key() {
    local name="$1"
    [ -n "$name" ] || name="$(lsshm_prompt "$(lsshm_t 'Host name')" '')"
    [ -n "$name" ] || { lsshm_info 'Cancelled.'; return 0; }
    local identity; identity="$(lsshm_hosts_get_field "$name" IdentityFile)"
    identity="$(lsshm_expand_user_path "${identity:-$(lsshm_keys_dir)/id_ed25519}")"
    local pub="$identity.pub"
    [ -f "$pub" ] || { lsshm_error 'Public key not found: %s' "$pub"; return 1; }
    local keytext; keytext="$(awk '{print $2}' "$pub")"
    [ -n "$keytext" ] || { lsshm_error 'Empty public key body.'; return 1; }
    # OpenSSH key bodies are base64; reject anything else before remote use.
    case "$keytext" in
        *[!A-Za-z0-9+/=]*)
            lsshm_error 'Invalid key body (unexpected characters).'
            return 1
            ;;
    esac
    lsshm_warn 'Removing the key on %s (requires authorized access).' "$name"
    lsshm_confirm "$(lsshm_t 'Continue?')" no || return 0
    # Pass the key body as argv ($1): SSH does not forward local env vars.
    # base64-only keytext is safe to embed via printf %q.
    if ssh "$name" "bash -s -- $(printf '%q' "$keytext")" <<'REMOTE'
set -euo pipefail
KEYBLOB="$1"
ak="${HOME}/.ssh/authorized_keys"
[ -f "$ak" ] || { echo "authorized_keys not found" >&2; exit 1; }
tmp="$(mktemp "${TMPDIR:-/tmp}/lsshm-ak.XXXXXX")"
awk -v k="$KEYBLOB" '
{
  keep=1
  for (i=1; i<=NF; i++) if ($i == k) keep=0
  if (keep) print
}' "$ak" >"$tmp"
mv "$tmp" "$ak"
chmod 600 "$ak"
REMOTE
    then
        lsshm_ok 'Key removed on %s.' "$name"
    else
        lsshm_error 'Removal failed.'
        return 1
    fi
}

# ===== src/known_hosts.sh ==============================================
# shellcheck shell=bash
# =============================================================================
# known_hosts.sh - manage ~/.ssh/known_hosts fingerprints
# =============================================================================

lsshm_known_hosts_file() {
    printf '%s/known_hosts' "$(lsshm_target_ssh_dir)"
}

lsshm_known_hosts_list() {
    local file; file="$(lsshm_known_hosts_file)"
    if [ ! -f "$file" ]; then
        lsshm_info 'No known_hosts file.'
        return 0
    fi
    lsshm_info 'Known fingerprints (%s):' "$file"
    ssh-keygen -lf "$file" 2>/dev/null || awk '{print $1}' "$file"
}

lsshm_known_hosts_show() {
    local host="$1"
    [ -n "$host" ] || host="$(lsshm_prompt "$(lsshm_t 'Server name or address')" '')"
    [ -n "$host" ] || return 1
    lsshm_info 'Host fingerprint for %s:' "$host"
    ssh-keygen -F "$host" 2>/dev/null || lsshm_warn 'No entry for %s.' "$host"
}

lsshm_known_hosts_remove() {
    local host="$1"
    [ -n "$host" ] || host="$(lsshm_prompt "$(lsshm_t 'Host to remove from known_hosts')" '')"
    [ -n "$host" ] || { lsshm_info 'Cancelled.'; return 0; }
    local file; file="$(lsshm_known_hosts_file)"
    [ -f "$file" ] || { lsshm_error 'No known_hosts file.'; return 1; }
    lsshm_backup_file "$file" "known-hosts" >/dev/null 2>&1 || true
    if ssh-keygen -R "$host" -f "$file" >/dev/null 2>&1; then
        lsshm_chown_user "$LSSHM_CALLING_USER" "$file"
        [ -f "${file}.old" ] && lsshm_chown_user "$LSSHM_CALLING_USER" "${file}.old"
        lsshm_ok 'Fingerprint of %s removed.' "$host"
    else
        lsshm_error 'Removal failed for %s.' "$host"
        return 1
    fi
}

lsshm_known_hosts_scan() {
    local host="$1"
    [ -n "$host" ] || host="$(lsshm_prompt "$(lsshm_t 'Host to scan')" '')"
    [ -n "$host" ] || return 1
    lsshm_have ssh-keyscan || { lsshm_error 'ssh-keyscan not found.'; return 1; }
    lsshm_info 'Fingerprint announced by %s:' "$host"
    ssh-keyscan "$host" 2>/dev/null | ssh-keygen -lf - 2>/dev/null
}

# ===== src/logs.sh =====================================================
# shellcheck shell=bash
# =============================================================================
# logs.sh - sessions, logins, and SSH service logs
# =============================================================================

lsshm_logs_sessions() {
    lsshm_info 'Active SSH sessions:'
    if lsshm_have who; then
        who 2>/dev/null | grep -Ei 'pts|ssh' || who 2>/dev/null || lsshm_info '  (none)'
    else
        lsshm_warn "'who' unavailable."
    fi
}

lsshm_logs_recent_logins() {
    lsshm_info 'Recent logins:'
    if lsshm_have last; then
        lsshm_run_privileged last -n 10 2>/dev/null | head -n 10 || true
    else
        lsshm_warn "'last' unavailable."
    fi
}

lsshm_logs_failed() {
    lsshm_info 'Recent failed login attempts:'
    if lsshm_have lastb; then
        lsshm_run_privileged lastb -n 10 2>/dev/null | head -n 10 || lsshm_info '  (none or not accessible)'
    elif [ -f /var/log/auth.log ]; then
        lsshm_run_privileged grep -i 'failed password' /var/log/auth.log 2>/dev/null | tail -n 10 || lsshm_info '  (none)'
    else
        lsshm_warn 'No source of failed attempts available.'
    fi
}

lsshm_logs_service() {
    lsshm_info 'SSH service logs:'
    lsshm_server_logs 40
}

lsshm_logs_menu() {
    while true; do
        local choice="" pick_ret=0
        if lsshm_uses_dialog_ui; then
            choice="$(lsshm_dialog_logs_menu)" || pick_ret=$?
            [ "$pick_ret" -ne 0 ] && break
        else
            clear 2>/dev/null || true
            lsshm_header
            lsshm_out 'Connections and logs'
            printf '\n'
            lsshm_out '  1. Active sessions'
            lsshm_out '  2. Recent logins'
            lsshm_out '  3. Failed attempts'
            lsshm_out '  4. SSH service logs'
            lsshm_out '  5. Back'
            choice="$(lsshm_prompt "$(lsshm_t 'Choice')" '5' || true)"
        fi
        case "$choice" in
            1) lsshm_ui_run "$(lsshm_t 'Active sessions')" lsshm_logs_sessions ;;
            2) lsshm_ui_run "$(lsshm_t 'Recent logins')" lsshm_logs_recent_logins ;;
            3) lsshm_ui_run "$(lsshm_t 'Failed attempts')" lsshm_logs_failed ;;
            4) lsshm_ui_run "$(lsshm_t 'SSH service logs')" lsshm_logs_service ;;
            5|q|Q) break ;;
            *) lsshm_warn 'Invalid choice.'; lsshm_uses_dialog_ui || lsshm_pause ;;
        esac
    done
}

# ===== src/audit.sh ====================================================
# shellcheck shell=bash
# =============================================================================
# audit.sh - local SSH security audit and diagnostics
# =============================================================================

LSSHM_AUDIT_PASS=0
LSSHM_AUDIT_WARN=0
LSSHM_AUDIT_FAIL=0

lsshm_audit_pass() { LSSHM_AUDIT_PASS=$((LSSHM_AUDIT_PASS+1)); printf '  [%sOK%s]   %s\n' "${LSSHM_C_GREEN:-}" "${LSSHM_C_RESET:-}" "$*"; }
lsshm_audit_warn() { LSSHM_AUDIT_WARN=$((LSSHM_AUDIT_WARN+1)); printf '  [%s%s%s] %s\n' "${LSSHM_C_YELLOW:-}" "$(lsshm_t 'WARN')" "${LSSHM_C_RESET:-}" "$*"; }
lsshm_audit_fail() { LSSHM_AUDIT_FAIL=$((LSSHM_AUDIT_FAIL+1)); printf '  [%s%s%s] %s\n' "${LSSHM_C_RED:-}" "$(lsshm_t 'FAIL')" "${LSSHM_C_RESET:-}" "$*"; }

lsshm_audit() {
    LSSHM_AUDIT_PASS=0; LSSHM_AUDIT_WARN=0; LSSHM_AUDIT_FAIL=0
    lsshm_header
    lsshm_out 'Local SSH security audit'
    printf '\n'

    printf '%s%s%s\n' "${LSSHM_C_BOLD:-}" "$(lsshm_t 'SSH server')" "${LSSHM_C_RESET:-}"
    if lsshm_server_is_installed; then
        lsshm_audit_pass "$(lsshm_t 'OpenSSH Server installed.')"
    else
        lsshm_audit_warn "$(lsshm_t 'OpenSSH Server not installed.')"
    fi

    local root pass maxauth
    root="$(lsshm_server_config_effective_value permitrootlogin)"
    case "$root" in
        no) lsshm_audit_pass "$(lsshm_t 'PermitRootLogin = no (root forbidden).')" ;;
        prohibit-password|without-password) lsshm_audit_pass "$(lsshm_t 'PermitRootLogin = key only.')" ;;
        yes) lsshm_audit_fail "$(lsshm_t 'PermitRootLogin = yes (root with password allowed).')" ;;
        *) lsshm_audit_warn "$(lsshm_tf 'PermitRootLogin = %s.' "${root:-$(lsshm_t 'not set')}")" ;;
    esac

    pass="$(lsshm_server_config_effective_value passwordauthentication)"
    case "$pass" in
        no) lsshm_audit_pass "$(lsshm_t 'Password authentication disabled.')" ;;
        yes) lsshm_audit_warn "$(lsshm_t 'Password authentication enabled.')" ;;
        *) lsshm_audit_warn "$(lsshm_tf 'PasswordAuthentication = %s.' "${pass:-$(lsshm_t 'not set')}")" ;;
    esac

    maxauth="$(lsshm_server_config_effective_value maxauthtries)"
    if [ -n "$maxauth" ] && [ "$maxauth" -le 4 ] 2>/dev/null; then
        lsshm_audit_pass "$(lsshm_tf 'MaxAuthTries = %s.' "$maxauth")"
    else
        lsshm_audit_warn "$(lsshm_tf 'MaxAuthTries = %s (recommended <= 4).' "${maxauth:-$(lsshm_t 'default')}")"
    fi

    if lsshm_server_is_installed && lsshm_server_config_test >/dev/null 2>&1; then
        lsshm_audit_pass "$(lsshm_t 'sshd -t: configuration valid.')"
    elif lsshm_server_is_installed; then
        lsshm_audit_fail "$(lsshm_t 'sshd -t: configuration invalid.')"
    fi

    printf '\n%s%s%s\n' "${LSSHM_C_BOLD:-}" "$(lsshm_tf 'Local permissions (%s)' "$LSSHM_CALLING_USER")" "${LSSHM_C_RESET:-}"
    local ssh_dir; ssh_dir="$(lsshm_target_ssh_dir)"
    if [ -d "$ssh_dir" ]; then
        local perm; perm="$(stat -c '%a' "$ssh_dir" 2>/dev/null || stat -f '%Lp' "$ssh_dir" 2>/dev/null)"
        if [ "$perm" = "700" ]; then
            lsshm_audit_pass "$(lsshm_t 'The .ssh directory has 700 permissions.')"
        else
            lsshm_audit_warn "$(lsshm_tf 'The .ssh directory has %s permissions (expected 700).' "${perm:-$(lsshm_t 'unknown')}")"
        fi
        local ak="$ssh_dir/authorized_keys"
        if [ -f "$ak" ]; then
            perm="$(stat -c '%a' "$ak" 2>/dev/null || stat -f '%Lp' "$ak" 2>/dev/null)"
            [ "$perm" = "600" ] && lsshm_audit_pass "$(lsshm_t 'authorized_keys 600.')" \
                || lsshm_audit_warn "$(lsshm_tf 'authorized_keys %s (expected 600).' "${perm:-$(lsshm_t 'unknown')}")"
        fi
        local priv
        for priv in "$ssh_dir"/id_*; do
            [ -f "$priv" ] || continue
            case "$priv" in *.pub) continue ;; esac
            perm="$(stat -c '%a' "$priv" 2>/dev/null || stat -f '%Lp' "$priv" 2>/dev/null)"
            [ "$perm" = "600" ] && lsshm_audit_pass "$(lsshm_tf '%s 600.' "$(basename "$priv")")" \
                || lsshm_audit_fail "$(lsshm_tf '%s %s (private key must be 600).' "$(basename "$priv")" "${perm:-$(lsshm_t 'unknown')}")"
        done
    else
        lsshm_audit_warn "$(lsshm_tf 'No .ssh directory for %s.' "$LSSHM_CALLING_USER")"
    fi

    printf '\n%s%s%s\n' "${LSSHM_C_BOLD:-}" "$(lsshm_t 'Listening port')" "${LSSHM_C_RESET:-}"
    if lsshm_server_port_listening; then
        lsshm_audit_pass "$(lsshm_t 'The configured SSH port is listening.')"
    else
        lsshm_audit_warn "$(lsshm_t 'Unable to confirm the SSH port is listening.')"
    fi

    printf '\n%s%s%s : %s\n' \
        "${LSSHM_C_BOLD:-}" "$(lsshm_t 'Summary')" "${LSSHM_C_RESET:-}" \
        "$(lsshm_tf '%d OK, %d warnings, %d failures' "$LSSHM_AUDIT_PASS" "$LSSHM_AUDIT_WARN" "$LSSHM_AUDIT_FAIL")"

    [ "$LSSHM_AUDIT_FAIL" -eq 0 ]
}

# Doctor: environment and configuration diagnostics.
lsshm_doctor() {
    lsshm_header
    lsshm_out 'LSSHM diagnostics (doctor)'
    printf '\n'
    lsshm_platform_summary
    printf '\n'
    lsshm_info 'SSH tools:'
    local t
    for t in ssh sshd ssh-keygen ssh-add ssh-copy-id ssh-keyscan; do
        if lsshm_have "$t"; then printf '  [OK]  %s\n' "$t"; else printf '  [--]  %s (%s)\n' "$t" "$(lsshm_t 'absent')"; fi
    done
    printf '\n'
    lsshm_info 'LSSHM paths:'
    printf '  config : %s\n' "$LSSHM_CONFIG_DIR"
    printf '  data   : %s\n' "$LSSHM_DATA_DIR"
    printf '  state  : %s\n' "$LSSHM_STATE_DIR"
    printf '  cache  : %s\n' "$LSSHM_CACHE_DIR"
    printf '\n'
    lsshm_info 'PATH:'
    case ":$PATH:" in
        *":$LSSHM_BIN_DIR:"*) printf '  [OK]  %s\n' "$(lsshm_tf '%s is in PATH' "$LSSHM_BIN_DIR")" ;;
        *) printf '  [--]  %s\n' "$(lsshm_tf '%s is not in PATH' "$LSSHM_BIN_DIR")" ;;
    esac
}

# ===== src/updater.sh ==================================================
# shellcheck shell=bash
# =============================================================================
# updater.sh - configuration file and safe self-update
# =============================================================================

# --- configuration file (INI-style key=value) --------------------------------

lsshm_config_default() {
    cat <<EOF
# LSSHM configuration
update_check=daily
update_channel=stable
EOF
}

lsshm_config_load() {
    LSSHM_CFG_UPDATE_CHECK="daily"
    LSSHM_CFG_UPDATE_CHANNEL="stable"
    LSSHM_CFG_LANG=""
    [ -r "$LSSHM_CONFIG_FILE" ] || return 0
    local line key val
    while IFS= read -r line; do
        case "$line" in ''|'#'*) continue ;; esac
        key="${line%%=*}"; val="${line#*=}"
        key="$(printf '%s' "$key" | tr -d '[:space:]')"
        val="$(printf '%s' "$val" | tr -d '[:space:]')"
        case "$key" in
            update_check)   LSSHM_CFG_UPDATE_CHECK="$val" ;;
            update_channel) LSSHM_CFG_UPDATE_CHANNEL="$val" ;;
            language)       LSSHM_CFG_LANG="$val" ;;
        esac
    done <"$LSSHM_CONFIG_FILE"
}

lsshm_config_write_default() {
    lsshm_ensure_dirs
    [ -f "$LSSHM_CONFIG_FILE" ] && return 0
    lsshm_config_default >"$LSSHM_CONFIG_FILE"
}

lsshm_config_set() {
    local key="$1" value="$2"
    lsshm_ensure_dirs
    [ -f "$LSSHM_CONFIG_FILE" ] || lsshm_config_default >"$LSSHM_CONFIG_FILE"
    local tmp; tmp="$(lsshm_mktemp)"
    if grep -q "^${key}=" "$LSSHM_CONFIG_FILE" 2>/dev/null; then
        sed "s|^${key}=.*|${key}=${value}|" "$LSSHM_CONFIG_FILE" >"$tmp"
    else
        cat "$LSSHM_CONFIG_FILE" >"$tmp"
        printf '%s=%s\n' "$key" "$value" >>"$tmp"
    fi
    install -m 0644 "$tmp" "$LSSHM_CONFIG_FILE"
}

# --- download helpers --------------------------------------------------------

lsshm_download() {
    # lsshm_download URL OUTFILE
    local url="$1" out="$2"
    if lsshm_have curl; then
        curl -fsSL "$url" -o "$out"
    elif lsshm_have wget; then
        wget -qO "$out" "$url"
    else
        lsshm_error 'Neither curl nor wget available for download.'
        return 1
    fi
}

lsshm_remote_version() {
    local tmp; tmp="$(lsshm_mktemp)"
    if lsshm_download "$LSSHM_REPO_RAW/VERSION" "$tmp" 2>/dev/null; then
        tr -d '[:space:]' <"$tmp"
    fi
}

lsshm_version_gt() {
    # returns 0 if $1 > $2 (semantic-ish numeric compare)
    [ "$1" = "$2" ] && return 1
    local greater
    greater="$(printf '%s\n%s\n' "$1" "$2" | sort -V | tail -n1)"
    [ "$greater" = "$1" ]
}

# --- update check ------------------------------------------------------------

lsshm_update_stamp() { printf '%s/last_update_check' "$LSSHM_CACHE_DIR"; }

lsshm_update_should_check() {
    lsshm_config_load
    case "$LSSHM_CFG_UPDATE_CHECK" in
        never) return 1 ;;
        always) return 0 ;;
        daily|*)
            local stamp; stamp="$(lsshm_update_stamp)"
            [ -f "$stamp" ] || return 0
            local last now
            last="$(cat "$stamp" 2>/dev/null || echo 0)"
            now="$(date +%s)"
            [ $((now - last)) -ge 86400 ]
            ;;
    esac
}

lsshm_update_touch_stamp() {
    lsshm_ensure_dirs
    date +%s >"$(lsshm_update_stamp)" 2>/dev/null || true
}

# Light check performed at startup.
lsshm_update_check() {
    lsshm_update_should_check || return 0
    lsshm_update_touch_stamp
    local remote; remote="$(lsshm_remote_version)"
    [ -n "$remote" ] || return 0
    if lsshm_version_gt "$remote" "$LSSHM_VERSION"; then
        printf '\n'
        lsshm_out 'Installed version: %s' "$LSSHM_VERSION"
        lsshm_out 'Available version: %s' "$remote"
        printf '\n'
        lsshm_out 'An update is available.'
        if lsshm_confirm "$(lsshm_t 'Install now?')" no; then
            lsshm_update_run
        fi
    fi
}

# --- safe update -------------------------------------------------------------

lsshm_update_run() {
    lsshm_ensure_dirs
    local target="$LSSHM_INSTALL_TARGET"
    if [ ! -f "$target" ]; then
        lsshm_warn 'LSSHM does not seem to be installed in %s.' "$target"
        lsshm_info 'Use: curl -fsSL %s/lsshm.sh | bash -s -- install' "$LSSHM_REPO_RAW"
        return 1
    fi

    local remote; remote="$(lsshm_remote_version)"
    lsshm_info 'Installed version: %s' "$LSSHM_VERSION"
    lsshm_info 'Remote version : %s' "${remote:-$(lsshm_t 'unknown')}"

    # 1. Download to a temporary file.
    local tmp; tmp="$(lsshm_mktemp)"
    lsshm_info 'Downloading the new version...'
    if ! lsshm_download "$LSSHM_REPO_RAW/lsshm.sh" "$tmp"; then
        lsshm_error 'Download failed.'
        return 1
    fi

    # 2. Validate syntax with bash -n.
    if ! bash -n "$tmp"; then
        lsshm_error 'The downloaded script has syntax errors. Aborting.'
        return 1
    fi

    # 3. Verify SHA-256 against the published SHA256SUMS.
    if ! lsshm_update_verify_checksum "$tmp"; then
        lsshm_error 'SHA-256 verification failed. Aborting.'
        return 1
    fi

    # 4. Sanity check: the new file must identify itself as LSSHM.
    if ! grep -q "LSSHM" "$tmp"; then
        lsshm_error 'The downloaded file does not look like LSSHM. Aborting.'
        return 1
    fi

    # 5/6. Keep previous version, then replace atomically.
    cp -a "$target" "$target.prev" 2>/dev/null || true
    chmod +x "$tmp"
    if install -m 0755 "$tmp" "$target"; then
        lsshm_ok 'Update installed. Previous version kept: %s' "$target.prev"
        lsshm_info "Use 'lsshm update rollback' to revert."
    else
        lsshm_error 'File replacement failed.'
        return 1
    fi
}

# Fail-closed: any missing tool, missing file, or mismatch aborts the caller.
lsshm_update_verify_checksum() {
    local file="$1"
    if [ ! -f "$file" ]; then
        lsshm_error 'File to verify not found.'
        return 1
    fi
    local sums; sums="$(lsshm_mktemp)"
    if ! lsshm_download "$LSSHM_REPO_RAW/SHA256SUMS" "$sums" 2>/dev/null; then
        lsshm_error 'SHA256SUMS unavailable: cannot verify (aborting).'
        return 1
    fi
    local expected actual
    # Accept both text ("hash  lsshm.sh") and binary ("hash *lsshm.sh") formats.
    expected="$(awk '
        {
            f = $2
            sub(/^\*/, "", f)
            if (f == "lsshm.sh") { print $1; exit }
        }
    ' "$sums")"
    if [ -z "$expected" ]; then
        lsshm_error 'lsshm.sh checksum missing from SHA256SUMS (aborting).'
        return 1
    fi
    if lsshm_have sha256sum; then
        actual="$(sha256sum "$file" | awk '{print $1}')"
    elif lsshm_have shasum; then
        actual="$(shasum -a 256 "$file" | awk '{print $1}')"
    else
        lsshm_error 'No SHA-256 tool (sha256sum/shasum): cannot verify (aborting).'
        return 1
    fi
    if [ "$expected" != "$actual" ]; then
        lsshm_error 'Incorrect SHA-256 checksum.'
        lsshm_error '  expected: %s' "$expected"
        lsshm_error '  actual:   %s' "$actual"
        return 1
    fi
    lsshm_ok 'SHA-256 checksum verified.'
    return 0
}

lsshm_update_rollback() {
    local target="$LSSHM_INSTALL_TARGET"
    if [ ! -f "$target.prev" ]; then
        lsshm_error 'No previous version available (%s).' "$target.prev"
        return 1
    fi
    lsshm_confirm "$(lsshm_t 'Restore the previous version of LSSHM?')" no || { lsshm_info 'Cancelled.'; return 0; }
    if install -m 0755 "$target.prev" "$target"; then
        lsshm_ok 'Previous version restored.'
    else
        lsshm_error 'Restore failed.'
        return 1
    fi
}

